// generated by tools/build_verse_manifests.js from ot_english.js — Dual-view English for the chapters of ot_verses/1ch.js
registerEnglish([["1 Chronicles",1,1,"Adam, Seth, Enos,"],["1 Chronicles",1,2,"Kenan, Mahalaleel, Jered,"],["1 Chronicles",1,3,"Henoch, Methuselah, Lamech,"],["1 Chronicles",1,4,"Noah, Shem, Ham, and Japheth."],["1 Chronicles",1,5,"The sons of Japheth; Gomer, and Magog, and Madai, and Javan, and Tubal, and Meshech, and Tiras."],["1 Chronicles",1,6,"And the sons of Gommer; Ashkenaz, and Difat, and Togarmah."],["1 Chronicles",1,7,"And the sons of Javan; Elisha, and Tarshisha, Kittim, and Dodanim."],["1 Chronicles",1,8,"The sons of Ham; Cush, and Egypt, Put, and Canaan."],["1 Chronicles",1,9,"And the sons of Cush; Sheba, and Havilah, and Sabtecha, and Ramah, and Sabtecha. And the sons of Ramah; Seba, and Dedan."],["1 Chronicles",1,10,"And Cush begot Nimrod: he began to be mighty upon the earth."],["1 Chronicles",1,11,"And Egypt begot Ludim, and Anamim, and Lehabim, and Naftuhim,"],["1 Chronicles",1,12,"and Pathrusim, and Casluhim, (of whom came to the Philistines,) and Caphtorim."],["1 Chronicles",1,13,"And Canaan begot Zidon his firstborn, and Heth,"],["1 Chronicles",1,14,"and the Jebusite, and the Amorite, and the Girgashite,"],["1 Chronicles",1,15,"and the Hivite and the Arkite, and the Sinite,"],["1 Chronicles",1,16,"and the Arvadite, and the Zemarite, and the Hamathite."],["1 Chronicles",1,17,"The sons of Shem; Elam, and Asshur, and Arphaxad, and Lud, and Aram, and Uz, and Hul, and Gether, and Meshech."],["1 Chronicles",1,18,"And Arphaxad begot Shelah, and Shelah begot Eber."],["1 Chronicles",1,19,"And to Eber were born two sons: the name of the one was Peleg; because in his days the earth was divided: and his brother's name was Joktan."],["1 Chronicles",1,20,"And Joktan begot Almodad, and Sheleph, and Hazarmaveth, and Jerah,"],["1 Chronicles",1,21,"and Hadoram, and Uzal, and Diklah,"],["1 Chronicles",1,22,"and Ebal, and Abimael, and Sheba,"],["1 Chronicles",1,23,"and Ophir, and Havilah, and Jobab. All these were the sons of Joktan."],["1 Chronicles",1,24,"Shem, Arphaxad, Shelah,"],["1 Chronicles",1,25,"Eber, Peleg, Reu,"],["1 Chronicles",1,26,"Serug, Nahor, Terah,"],["1 Chronicles",1,27,"Abram; the same is Abraham."],["1 Chronicles",1,28,"The sons of Abraham; Isaac, and Ishmael."],["1 Chronicles",1,29,"These are their generations: The firstborn of Ishmael, Nebaioth; then Kedar, and Adbeel, and Mibsam,"],["1 Chronicles",1,30,"Mishma, and Dumah, Massa, Hadad, and Tema,"],["1 Chronicles",1,31,"Jetur, Naphish, and Kedemah. These are the sons of Ishmael."],["1 Chronicles",1,32,"Now the sons of Keturah, Abraham's concubine: she bore Zimran, and Jokshan, and Medan, and Midian, and Ishbak, and Shuah. And the sons of Jokshan; Sheba, and Dedan."],["1 Chronicles",1,33,"And the sons of Midian; Ephah, and Epher, and Henoch, and Abida, and Eldaah. All these are the sons of Keturah."],["1 Chronicles",1,34,"And Abraham begot Isaac. The sons of Isaac; Esau and Israel."],["1 Chronicles",1,35,"The sons of Esau; Eliphaz, Reuel, and Jeush, and Jaalam, and Korah."],["1 Chronicles",1,36,"The sons of Eliphaz; Teman, and Omar, Zephi, and Gatam, Kenaz, and Teman, and Amalek."],["1 Chronicles",1,37,"The sons of Reuel; Nahath, Zerah, Shammah, and Mizzah."],["1 Chronicles",1,38,"And the sons of Seir; Lotan, and Shobal, and Zibeon, and Anah, and Dishon, and Ezer, and Dishan."],["1 Chronicles",1,39,"And the sons of Lotan; Hori, and Homam: and Timnah was Lotan's sister."],["1 Chronicles",1,40,"The sons of Shobal; Alian, and Manahath, and Ebal, Shephi, and Onam. And the sons of Zibeon; Aiah, and Anah."],["1 Chronicles",1,41,"The sons of Anah; Dishon. And the sons of Dishon; Hamran, and Eshban, and Ithran, and Cheran."],["1 Chronicles",1,42,"The sons of Ezer; Bilhan, and Zaavan, and Jaakan. The sons of Dishan; Uz, and Aran."],["1 Chronicles",1,43,"Now these are the kings who reigned in the land of Edom before any king reigned over the children of Israel; Bela the son of Beor: and the name of his city was Dinhabah."],["1 Chronicles",1,44,"And when Bela was dead, Jobab the son of Zerah of Bozrah reigned in his place."],["1 Chronicles",1,45,"And when Jobab was dead, Husham of the land of the Temani reigned in his place."],["1 Chronicles",1,46,"And when Husham was dead, Hadad the son of Bedad, who smote Midian in the field of Moab, reigned in his place: and the name of his city was Avith."],["1 Chronicles",1,47,"And when Hadad was dead, Samlah of Masrekah reigned in his place."],["1 Chronicles",1,48,"And when Samlah was dead, Shaul of Rehoboth by the river reigned in his place."],["1 Chronicles",1,49,"And when Shaul was dead, Baal-hanan the son of Achbor reigned in his place."],["1 Chronicles",1,50,"And when Baal-hanan was dead, Hadad reigned in his place: and the name of his city was Pai; and his wife's name was Mehetabel, the daughter of Matred, the daughter of Mezahab."],["1 Chronicles",1,51,"Hadad died also. And the chiefs of Edom were; chief Timnah, chief Alvah, chief Jetheth,"],["1 Chronicles",1,52,"chief Aholibamah, chief Elah, chief Pinon,"],["1 Chronicles",1,53,"chief Kenaz, chief Teman, chief Mibzar,"],["1 Chronicles",1,54,"chief Magdiel, chief Iram. These are the chiefs of Edom."],["1 Chronicles",2,1,"These are the sons of Israel; Reuben, Simeon, Levi, and Judah, Issachar, and Zebulun,"],["1 Chronicles",2,2,"Dan, Joseph, and Benjamin, Naphtali, Gad and Asher."],["1 Chronicles",2,3,"The sons of Judah; Er, and Onan, and Shelah: which three were born to him of the daughter of Shua the Canaanite woman. And Er, the firstborn of Judah, was evil in the sight of the Lord; and he slew him."],["1 Chronicles",2,4,"And Tamar his daughter in law bore him Pharez and Zerah. All the sons of Judah were five."],["1 Chronicles",2,5,"The sons of Pharez; Hezron, and Hamul."],["1 Chronicles",2,6,"And the sons of Zerah; Zimri, and Ethan, and Heman, and Calcol, and Dare: five of them in all."],["1 Chronicles",2,7,"And the sons of Carmi; Achar, the troubler of Israel, who transgressed in the devoted property."],["1 Chronicles",2,8,"And the sons of Ethan; Azariah."],["1 Chronicles",2,9,"And the sons of Hezron, that were born to him; Jerahmeel, and Ram, and Chelubai."],["1 Chronicles",2,10,"And Ram begot Amminadab; and Amminadab begot Nahshon, prince of the children of Judah;"],["1 Chronicles",2,11,"and Nahshon begot Salma, and Salma begot Boaz,"],["1 Chronicles",2,12,"and Boaz begot Obed, and Obed begot Jesse,"],["1 Chronicles",2,13,"and Ishai begot his firstborn Eliab, and Abinadab the second, and Shimea the third,"],["1 Chronicles",2,14,"Nethaneel the fourth, Raddai the fifth,"],["1 Chronicles",2,15,"Ozem the sixth, David the seventh:"],["1 Chronicles",2,16,"whose sisters were Zeruiah, and Abigail. And the sons of Zeruiah; Abishai, and Joab, and Asahel; three."],["1 Chronicles",2,17,"And Abigail bore Amasa: and the father of Amasa was Jether the Ishmaelite."],["1 Chronicles",2,18,"And Caleb the son of Hezron, begot children by Azubah his wife, and by Jerioth: her sons are these; Jesher, and Shobab, and Ardon."],["1 Chronicles",2,19,"And when Azubah was dead, Caleb took to him Ephratah, who bore him Hur."],["1 Chronicles",2,20,"And Hur begot Uri, and Uri begot Bezaleel."],["1 Chronicles",2,21,"And afterwards Hezron went in to the daughter of Machir the father of Gilead, whom he married when he was sixty years old; and she bore him Segub."],["1 Chronicles",2,22,"And Segub begot Jair, who had twenty three cities in the land of Gilead."],["1 Chronicles",2,23,"And he took Geshur, and Aram, with Havoth-jair, from them, with Kenath, and its hamlets, sixty cities. All these belonged to the sons of Machir the father of Gilead."],["1 Chronicles",2,24,"And after Hezron had died in Caleb-ephratah, then Abijah, Hezron's wife bore him Ashur the father of Tekoa."],["1 Chronicles",2,25,"And the sons of Jerahmeel the firstborn of Hezron were, Ram the firstborn, and Bunah, and Oren, and Ozem, and Ahijah."],["1 Chronicles",2,26,"Jerahmeel had also another wife, whose name was Atarah; she was the mother of Onam."],["1 Chronicles",2,27,"And the sons of Ram the firstborn of Jerahmeel were, Maaz, and Jamin, and Eker."],["1 Chronicles",2,28,"And the sons of Onam were, Shammai, and Jada. And the sons of Shammai; Nadab, and Abishur."],["1 Chronicles",2,29,"And the name of the wife of Abishur was Abihail, and she bore him Ahban, and Molid."],["1 Chronicles",2,30,"And the sons of Nadab; Seled, and Appaim; but Seled died without children."],["1 Chronicles",2,31,"And the sons of Appaim; Ishi, And the sons of Ishi; Sheshan. And the children of Sheshan; Ahlai."],["1 Chronicles",2,32,"And the sons of Jada the brother of Shammai; Jether, and Jonathan: and Jether died without children."],["1 Chronicles",2,33,"And the sons of Jonathan; Pelet, and Zaza. These were the sons of Jerahmeel."],["1 Chronicles",2,34,"Now Sheshan had no sons, but only daughters. And Sheshan had a slave, a Egyptian, whose name was Jarha."],["1 Chronicles",2,35,"And Sheshan gave his daughter to Jarha his slave to wife; and she bore him Attai."],["1 Chronicles",2,36,"And Attai begot Nathan, and Nathan begot Zabad."],["1 Chronicles",2,37,"and Zabad begot Ephlal, and Ephlal begot Obed,"],["1 Chronicles",2,38,"and Obed begot Jehu, and Jehu begot Azariah,"],["1 Chronicles",2,39,"and Azariah begot Helez, and Helez begot Eleasah,"],["1 Chronicles",2,40,"and Eleasah begot Sisamai, and Sisamai begot Shallum,"],["1 Chronicles",2,41,"and Shallum begot Jekamiah, and Jekamiah begot Elishama."],["1 Chronicles",2,42,"Now the sons of Caleb the brother of Jerahmeel were, Mesha his firstborn, who was the father of Ziph; and the sons of Mareshah the father of Hebron."],["1 Chronicles",2,43,"And the sons of Hebron; Korah, and Tappuah, and Rekem, and Shema."],["1 Chronicles",2,44,"And Shema begot Raham, the father of Jorkoam: and Rekem begot Shammai."],["1 Chronicles",2,45,"And the son of Shammai was Maon: and Maon was the father of Beth-zur."],["1 Chronicles",2,46,"And Ephah, Caleb's concubine, bore Haran, and Moza, and Gazez: and Haran begot Gazez."],["1 Chronicles",2,47,"And the sons of Jahdai; Regem, and Jotham, and Geshan, and Pelet, and Ephah, and Shaaph."],["1 Chronicles",2,48,"Maachah, Caleb's concubine, bore Sheber, and Tirhanah."],["1 Chronicles",2,49,"She bore also Shaaph the father of Madmannah, Sheva the father of Machbenah, and the father of Gibeah: and the daughter of Caleb was Achsah."],["1 Chronicles",2,50,"These were the sons of Caleb the son of Hur, the firstborn of Ephratah; Shobal the father of Kirjath-jearim,"],["1 Chronicles",2,51,"Salma the father of Beth-lehem, Hareph the father of Beth-gader."],["1 Chronicles",2,52,"And Shobal the father of Kirjath-jearim had sons; Haroeh, and half of the Menuhot."],["1 Chronicles",2,53,"And the families of Kirjath-jearim; the Jitri, and the Puhites, and the Shumathites, and the Mishraites; of them came the Zorathites, and the Eshtaulites."],["1 Chronicles",2,54,"The sons of Salma; Beth-lehem, and the Netophathites, Atrot-bet-joab, and half the Manahti, and the Zorites."],["1 Chronicles",2,55,"And the families of the scribes who dwelt at Jabez; the Tirathites, the Shimeathites, the Suchathites. These are the Qinim who came of Hamath, the father of the house of Rechab."],["1 Chronicles",3,1,"Now these were the sons of David, who were born to him in Hebron; the firstborn Amnon, of Ahinoam the Jezreelitess woman; Daniel of Abigail the Carmelite woman:"],["1 Chronicles",3,2,"the third, Absalom the son of Maachah the daughter of Talmai king of Geshur: the fourth, Adonijah the son of Haggith:"],["1 Chronicles",3,3,"the fifth, Shephatiah of Abital: the sixth, Ithream by Eglah his wife."],["1 Chronicles",3,4,"These six were born to him in Hebron; and there he reigned seven years and six months: and in Jerusalem he reigned thirty three years."],["1 Chronicles",3,5,"And these were born to him in Jerusalem; Shimea, and Shobab, and Nathan, and Solomon; four, of Bat-Shua the daughter of Ammiel:"],["1 Chronicles",3,6,"and Ibhar, and Elishama, and Eliphelet,"],["1 Chronicles",3,7,"and Nogah, and Nepheg, and Japhia,"],["1 Chronicles",3,8,"and Elishama, and Eliada, and Eliphelet; nine."],["1 Chronicles",3,9,"These were all the sons of David, besides the sons of the concubines, and Tamar their sister."],["1 Chronicles",3,10,"And Solomon's son was Rehoboam, Abijah his son, Asa his son, Jehoshaphat his son,"],["1 Chronicles",3,11,"Joram his son, Ahaziah his son, Joash his son,"],["1 Chronicles",3,12,"Amaziah his son, Azariah his son, Jotham his son,"],["1 Chronicles",3,13,"Ahaz his son, Hezekiah his son, Manasseh his son,"],["1 Chronicles",3,14,"Amon his son, Josiah his son."],["1 Chronicles",3,15,"And the sons of Josiah were, the firstborn Johanan, the second Jehoiakim, the third Zedekiah, the fourth Shallum."],["1 Chronicles",3,16,"And the sons of Jehoiakim: Jeconiah his son, Zedekiah his son."],["1 Chronicles",3,17,"And the sons of Jeconiah; Assir, Shealtiel his son."],["1 Chronicles",3,18,"and Malchiram, and Pedaiah, and Shenazar, Jekamiah, Hoshama, and Nedabiah."],["1 Chronicles",3,19,"And the sons of Pedaiah were, Zerubbabel, and Shimei: and the sons of Zerubbabel; Meshullam, and Hananiah and Shelomith their sister:"],["1 Chronicles",3,20,"and Hashubah, and Ohel, and Berechiah, and Hasadiah, Jushab-hesed; five."],["1 Chronicles",3,21,"And the sons of Hananiah; Pelatiah, and Jeshaaia: the sons of Rephaiah, the sons of Arnan, the sons of Obadiah, the sons of Shechaniah."],["1 Chronicles",3,22,"And the sons of Shechaniah; Shemaiah: and the sons of Shemaiah; Hattush, and Igal, and Bariah, and Neariah; and Shaphat, six."],["1 Chronicles",3,23,"And the sons of Neariah; Elioenai, and Hezekiah, and Azrikam; three."],["1 Chronicles",3,24,"And the sons of Elioenai were, Hodaviah, and Eliashib, and Pelaiah, and Akkub, and Johanan, and Delaiah, and Anani; seven."],["1 Chronicles",4,1,"The sons of Judah; Pharez, Hezron, and Carmi, and Hur, and Shobal."],["1 Chronicles",4,2,"And Reaiah the son of Shobal begot Jahath; and Jahath begot Ahumai, and Lahad. These are the families of the Zorathites."],["1 Chronicles",4,3,"And these were of the father of Etam; Jezreel, and Ishma, and Idbash: and the name of their sister was Hazelelponi;"],["1 Chronicles",4,4,"and Penuel the father of Gedor, and Ezer the father of Hushah. These are the sons of Hur, the firstborn of Ephratah, the father of Beth-lehem."],["1 Chronicles",4,5,"And Ashur the father of Tekoa had two wives, Helah and Naarah."],["1 Chronicles",4,6,"And Naarah bore him Ahuzam, and Hepher, and Temeni, and Haahashtari. These were the sons of Naarah."],["1 Chronicles",4,7,"And the sons of Helah were, Zereth, and Zohar, and Ethnan."],["1 Chronicles",4,8,"And Coz begot Anub, and Zobebah, and the families of Aharhel the son of Harum."],["1 Chronicles",4,9,"And Jabez was more honourable than his brothers; and his mother called his name Jabez, saying, Because I bore him with pain."],["1 Chronicles",4,10,"And Jabez called on the God of Israel, saying, Oh that Thou wouldst bless me indeed, and enlarge my border, and that Thy hand might be with me, and that Thou wouldst keep me from harm, that it may not hurt me! And God granted him that which he requested."],["1 Chronicles",4,11,"And Chelub the brother of Shuha begot Mehir, who was the father of Eshton."],["1 Chronicles",4,12,"And Eshton begot Beth-rapha, and Paseah, and Tehinnah the father of Ir-nahash. These are the men of Rechah."],["1 Chronicles",4,13,"And the sons of Kenaz; Othniel, and Seraiah: and the sons of Othniel: Hathath."],["1 Chronicles",4,14,"And Meonothai begot Ophrah: and Seraiah begot Joab, the father of the Charashim; for they were craftsmen."],["1 Chronicles",4,15,"And the sons of Caleb the son of Jephunneh; Iru, Elah, and Naam: and the sons of Elah, even Kenaz."],["1 Chronicles",4,16,"And the sons of Jehaleleel; Ziph, and Ziph, Tiria, and Asareel."],["1 Chronicles",4,17,"And the sons of Ezra were, Jether, and Mered, and Epher, and Jalon: and she conceived Miriam, and Shammai, and Ishbah the father of Eshtemoa."],["1 Chronicles",4,18,"And his wife Jehudijah bore Jered the father of Gedor, and Heber the father of Shocho, and Jekuthiel the father of Zanoah. And these are the sons of Bitya the daughter of Pharaoh whom Mered took."],["1 Chronicles",4,19,"And the sons of the wife of Hodiah the sister of Naham, the father of Keilah the Garmite, and Eshtemoa the Maachathite."],["1 Chronicles",4,20,"And the sons of Simeon were, Amnon, and Rinnah, Ben-hanan, and Tilon. And the sons of Ishi were, Zoheth, and Ben-zoheth."],["1 Chronicles",4,21,"The sons of Shelah the son of Judah were, Er the father of Lecah, and Laadah the father of Mareshah, and the families of the house of the linen workers, of the house of Ashbea,"],["1 Chronicles",4,22,"and Jokim, and the men of Chozeba, and Joash, and Saraph, who ruled in Moab, and Jashubi-lehem (But the records are ancient.)"],["1 Chronicles",4,23,"These were the potters, and those who dwelt among plantations and hedges: there they dwelt, occupied with the king's work."],["1 Chronicles",4,24,"The sons of Simeon were, Nemuel, and Jamin, Jarib, Zerah and Shaul:"],["1 Chronicles",4,25,"Shallum his son, Mibsam his son, Mishma his son."],["1 Chronicles",4,26,"And the sons of Mishma; Hamuel his son, Zaccur his son, Shimei his son."],["1 Chronicles",4,27,"And Shimei had sixteen sons and six daughters; but his brothers had not many children, nor did all their family multiply, like the children of Judah."],["1 Chronicles",4,28,"And they dwelt at Beer-sheba, and Moladah, and Hazar-shual."],["1 Chronicles",4,29,"and at Bilhah, and at Ezem, and at Tolad,"],["1 Chronicles",4,30,"and at Bethuel, and at Hormah, and at Ziklag,"],["1 Chronicles",4,31,"and at Beth-marcaboth, and Hazar-susim, and at Beth-birei, and at Shaaraim. These were their cities until the reign of David."],["1 Chronicles",4,32,"And their settlements were, Etam, and Ain, Rimmon, and Tochen, and Ashan; five cities:"],["1 Chronicles",4,33,"and all their settlements that were round about the same cities as far as Baal. These were their habitations, and their genealogy."],["1 Chronicles",4,34,"And Meshobab, and Jamlech, and Joshah the son of Amaziah."],["1 Chronicles",4,35,"And Joel, and Jehu the son of Josibiah, the son of Seraiah, the son of Asiel,"],["1 Chronicles",4,36,"and Elioenai, and Jaakobah, and Jeshohaiah, and Asaiah, and Adiel, and Jesimiel, and Benaiah."],["1 Chronicles",4,37,"and Ziza the son of Shiphi, the son of Allon, the son of Jedaiah, the son of Shimri, the son of Shemaiah;"],["1 Chronicles",4,38,"these mentioned by their names were princes in their families: and the house of their fathers increased greatly."],["1 Chronicles",4,39,"And they went to the entrance of Gedor, as far as the east side of the valley, to seek pasture for their flocks."],["1 Chronicles",4,40,"And they found rich, good pasture, and the land was wide, and quiet, and peaceable; for they of Ham had dwelt there of old."],["1 Chronicles",4,41,"And these written by name came in the days of Hezekiah king of Judah, and smote their tents, and the Mehunim who were found there, and destroyed them utterly unto this day, and dwelt in their stead: because there was pasture there for their flocks."],["1 Chronicles",4,42,"And some of them, of the sons of Simeon, five hundred men, went to mount Seir, having as their leaders Pelatiah, and Neariah, and Rephaiah, and Uzziel, the sons of Ishi."],["1 Chronicles",4,43,"And they smote the remnant of Amalek who had escaped, and dwelt there to this day."],["1 Chronicles",5,1,"Now the sons of Reuben the firstborn of Israel, (for he was the firstborn; but, since he defiled his father's bed, his birthright was given to the sons of Joseph the son of Israel: but not so as to have the birthright attributed to him by genealogy."],["1 Chronicles",5,2,"For Judah prevailed over his brothers, and of him came the chief ruler; though the birthright was Joseph's:)"],["1 Chronicles",5,3,"the sons of Reuben the firstborn of Israel were, Hanoch, and Pallu, Hezron, and Carmi."],["1 Chronicles",5,4,"The sons of Joel; Shemaiah his son, Gog his son, Shimei his son,"],["1 Chronicles",5,5,"Micah his son, Reaiah his son, Baal his son,"],["1 Chronicles",5,6,"Beera his son, whom Tilgath-pilneser king of Assyria carried away into exile: he was prince of the Reubenites."],["1 Chronicles",5,7,"And his brothers by their families, when the genealogy of their generations was reckoned, were the chief, Jeiel, and Zechariah,"],["1 Chronicles",5,8,"and Bela the son of Azaz, the son of Shema, the son of Joel, who dwelt in Aroer, as far as Nebo and Baal-meon:"],["1 Chronicles",5,9,"and eastward he inhabited as far as the entrance of the wilderness from the river Euphrates: because their cattle had multiplied in the land of Gilead."],["1 Chronicles",5,10,"And in the days of Saul they made war with the Hagarites, who fell by their hand: and they dwelt in their tents throughout all the east land of Gilead."],["1 Chronicles",5,11,"And the children of Gad dwelt opposite them, in the land of the Bashan as far as Salchah:"],["1 Chronicles",5,12,"Joel the chief, and Shapham the next, and Janai, and Shaphat in the Bashan."],["1 Chronicles",5,13,"And their brethren of the house of their fathers were, Michael, and Meshullam, and Sheba, and Jorai, and Jachan, and Zia, and Eber; seven."],["1 Chronicles",5,14,"These are the children of Abihail the son of Huri, the son of Jaroah, the son of Gilead, the son of Michael, the son of Jeshishai, the son of Jahdo, the son of Buz;"],["1 Chronicles",5,15,"Ahi the son of Abdiel, the son of Guni, chief of the house of their fathers."],["1 Chronicles",5,16,"And they dwelt in Gilead in the Bashan, and in its hamlets, and in all the pasture lands of Sharon, to their limits."],["1 Chronicles",5,17,"All these were reckoned by genealogies in the days of Jotham king of Judah, and in the days of Jeroboam king of Israel."],["1 Chronicles",5,18,"The sons of Reuben, and the Gadites, and half the tribe of Manasseh, of men at arms, able to bear shield and sword, and to draw the bow, and skilful in war, were forty four thousand seven hundred and sixty, who went out to war."],["1 Chronicles",5,19,"And they made war with the Hagarites, with Jetur, and Naphish, and Nodab."],["1 Chronicles",5,20,"And they were helped against them, and the Hagarites were delivered into their hand, and all that were with them: for they cried to God in the battle, and he granted their entreaty: because they put their trust in him."],["1 Chronicles",5,21,"And they took away their cattle; of their camels fifty thousand, and of sheep two hundred and fifty thousand, and of asses two thousand, and of men a hundred thousand."],["1 Chronicles",5,22,"For there fell down many slain, because the war was from God. And they dwelt in their stead until the exile."],["1 Chronicles",5,23,"And the children of the half tribe of Manasseh dwelt in the land: they increased from Bashan to Baal-hermon and Senir, and to mount Hermon."],["1 Chronicles",5,24,"And these were the heads of the houses of their fathers, Epher, and Ishi, and Eliel, and Azriel, and Jeremiah, and Hodaviah, and Jahdiel, mighty men of valour, famous men, and heads of the houses of their fathers."],["1 Chronicles",5,25,"And they transgressed against the God of their fathers, and went astray after the gods of the peoples of the land, whom God destroyed before them."],["1 Chronicles",5,26,"And the God of Israel stirred up the spirit of Pul king of Assyria, and the spirit of Tilgath-pilneser king of Assyria, and he carried them away, namely the Reubenites, and the God, and the half tribe of Manasseh, and brought them to Halah, and Habor, and Hara, and to the river Gozan, to this day."],["1 Chronicles",5,27,"The sons of Levi; Gershon, Kohath, and Merari."],["1 Chronicles",5,28,"And the sons of Kohath; Amram, Izhar, and Hebron, and Uzziel."],["1 Chronicles",5,29,"And the children of Amram: Aaron, and Moses, and Miriam. And the sons of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."],["1 Chronicles",5,30,"Eleazar begot Phinehas, Phinehas begot Abishua,"],["1 Chronicles",5,31,"and Abishua begot Bukki, and Bukki begot Uzzi,"],["1 Chronicles",5,32,"and Uzzi begot Zerahiah, and Zerahiah begot Meraioth;"],["1 Chronicles",5,33,"Meraioth begot Amariah, and Amariah begot Ahitub,"],["1 Chronicles",5,34,"and Ahitub begot Zadok, and Zadok begot Ahimaaz,"],["1 Chronicles",5,35,"and Ahimaaz begot Azariah, and Azariah begot Johanan,"],["1 Chronicles",5,36,"and Johanan begot Azariah, (he it is who executed the priest's office in the temple that Solomon built in Jerusalem:)"],["1 Chronicles",5,37,"and Azariah begot Amariah, and Amariah begot Ahitub,"],["1 Chronicles",5,38,"and Ahitub begot Zadok, and Zadok begot Shallum,"],["1 Chronicles",5,39,"and Shallum begot Hilkiah, and Hilkiah begot Azariah,"],["1 Chronicles",5,40,"and Azariah begot Seraiah, and Seraiah begot Josedech,"],["1 Chronicles",5,41,"and Josedech went into exile, when the Lord carried away Judah and Jerusalem by the hand of Nebuchadnezzar."],["1 Chronicles",6,1,"The sons of Levi; Gershom, Kohath, and Merari."],["1 Chronicles",6,2,"And these are the names of the sons of Gershom; Libni, and Shimei."],["1 Chronicles",6,3,"And the sons of Kohath were, Amram, and Izhar, and Hebron, and Uzziel."],["1 Chronicles",6,4,"The sons of Merari; Mahli, and Mushi. And these are the families of the Levites according to their fathers."],["1 Chronicles",6,5,"Of Gershom; Libni his son, Jahath his son, Zimmah his son,"],["1 Chronicles",6,6,"Joah his son, Iddo his son, Zerah his son, Jeaterai his son."],["1 Chronicles",6,7,"The sons of Kohath; Amminadab his son, Korah his son, Assir his son,"],["1 Chronicles",6,8,"Elkanah his son, and Ebiasaph his son, and Assir his son,"],["1 Chronicles",6,9,"Tahath his son, Uriel his son, Uzziah his son, and Shaul his son."],["1 Chronicles",6,10,"And the sons of Elkanah; Amasai, and Ahimoth."],["1 Chronicles",6,11,"As for Elkanah: the sons of Elkanah; Zophai his son, and Nahath his son."],["1 Chronicles",6,12,"Eliab his son, Jeroham his son, Elkanah his son."],["1 Chronicles",6,13,"And the sons of Shemuel; the firstborn Vashni, and Abijah."],["1 Chronicles",6,14,"The sons of Merari; Mahli, Libni his son, Shimei his son, Uzza his son,"],["1 Chronicles",6,15,"Shimea his son, Haggiah his son, Asaiah his son."],["1 Chronicles",6,16,"And these are they whom David set over the service of song in the house of the Lord, after the ark had rest."],["1 Chronicles",6,17,"And they ministered before the dwelling place of the Tent of Meeting with singing, until Solomon had built the house of the Lord in Jerusalem: and then they performed their office according to their order."],["1 Chronicles",6,18,"And these are the men who served with their sons. Of the sons of the Kohathites; Heman the singer, the son of Joel, the son of Shemuel,"],["1 Chronicles",6,19,"the son of Elkanah, the son of Jeroham, the son of Eliel, the son of Toah,"],["1 Chronicles",6,20,"the son of Zuph, the son of Elkanah, the son of Mahath, the son of Amasai,"],["1 Chronicles",6,21,"the son of Elkanah, the son of Joel, the son of Azariah, the son of Zephaniah,"],["1 Chronicles",6,22,"the son of Tahath, the son of Assir, the son of Ebiasaph, the son of Korah,"],["1 Chronicles",6,23,"the son of Izhar, the son of Kohath, the son of Levi, the son of Israel,"],["1 Chronicles",6,24,"and his brother Asaph, who stood on his right hand, Asaph the son of Berechiah, son of Shimea,"],["1 Chronicles",6,25,"the son of Michael, the son of Baaseiah, the son of Malchijah,"],["1 Chronicles",6,26,"the son of Ethni, the son of Zerah, the son of Adaiah,"],["1 Chronicles",6,27,"the son of Ethan, the son of Zimmah, the son of Shimei,"],["1 Chronicles",6,28,"the son of Jahath, the son of Gershom, the son of Levi."],["1 Chronicles",6,29,"And their brethren the sons of Merari stood on the left hand: Ethan the son of Kishi, the son of Abdi, the son of Malluch,"],["1 Chronicles",6,30,"the son of Hashabiah, the son of Amaziah, the son of Hilkiah,"],["1 Chronicles",6,31,"the son of Amzi, the son of Bani, the son of Shemer,"],["1 Chronicles",6,32,"the son of Mahli, the son of Mushi, the son of Merari, the son of Levi."],["1 Chronicles",6,33,"And their brethren the Levites were appointed to all manner of service of the tabernacle of the house of God."],["1 Chronicles",6,34,"But Aaron and his sons offered upon the altar of the burnt offering, and on the altar of incense, for all the work of the most holy place, and to make atonement for Israel, according to all that Moses the servant of God had commanded."],["1 Chronicles",6,35,"And these are the sons of Aaron; Eleazar his son, Phinehas his son, Abishua his son,"],["1 Chronicles",6,36,"Bukki his son, Uzzi his son, Zerahiah his son,"],["1 Chronicles",6,37,"Meraioth his son, Amariah his son, Ahitub his son,"],["1 Chronicles",6,38,"Zadok his son, Ahimaaz his son."],["1 Chronicles",6,39,"Now these are their dwelling places throughout their encampments in their borders, of the sons of Aaron, of the families of the Kohathites: for theirs was the lot."],["1 Chronicles",6,40,"And they gave them Hebron in the land of Judah, and its pasture lands round about it."],["1 Chronicles",6,41,"But the fields of the city, and its farmsteads, they gave to Caleb the son of Jephunneh."],["1 Chronicles",6,42,"And to the sons of Aaron they gave the cities of refuge, Hebron, and Libnah with its pasture lands, and Jattir, and Eshtemoa, with its pasture lands,"],["1 Chronicles",6,43,"and Hilen with its pasture lands, Debir with its pasture lands,"],["1 Chronicles",6,44,"and Ashan with its pasture lands, and Beth-shemesh with its pasture lands:"],["1 Chronicles",6,45,"and out of the tribe of Benjamin; Geba with its pasture lands, and Alemeth with its pasture lands, and Anathoth with its pasture lands. All their cities throughout their families were thirteen cities."],["1 Chronicles",6,46,"And to the rest of the sons of Kohath, were given by lot, out of the family of that tribe, out of the half tribe, the half of Manasseh, ten cities."],["1 Chronicles",6,47,"And to the sons of Gershom according to their families out of the tribe of Issachar, and out of the tribe of Asher, and out of the tribe of Naphtali, and out of the tribe of Manasseh in the Bashan, thirteen cities."],["1 Chronicles",6,48,"To the sons of Merari were given by lot, according to their families, out of the tribe of Reuben, and out of the tribe of Gad, and out of the tribe of Zebulun, twelve cities."],["1 Chronicles",6,49,"And the children of Israel gave to the Levites these cities with their pasture lands."],["1 Chronicles",6,50,"And they gave by lot out of the tribe of the children of Judah and out of the tribe of the children of Simeon, and out of the tribe of the children of Benjamin, these cities, which are mentioned by names."],["1 Chronicles",6,51,"And some of the families of the sons of Kohath had cities of their borders out of the tribe of Ephraim."],["1 Chronicles",6,52,"For they gave to them the cities of refuge, Shechem in mount Ephraim with its pasture lands; and Gezer with its pasture lands,"],["1 Chronicles",6,53,"and Jokmeam with its pasture lands, and Beth-horon with its pasture lands,"],["1 Chronicles",6,54,"and Aijalon with its pasture lands, and Gath-rimmon with its pasture lands:"],["1 Chronicles",6,55,"and out of the half tribe of Manasseh; Aner with its pasture lands, and Balaam with its pasture lands, for the family of the remnant of the sons of Kohath."],["1 Chronicles",6,56,"To the sons of Gershom were given out of the family of the half tribe of Manasseh, Golan in the Bashan with its pasture lands, and Ashtaroth with its pasture lands:"],["1 Chronicles",6,57,"and out of the tribe of Issachar; Kedesh with its pasture lands, Daberath, with its pasture lands,"],["1 Chronicles",6,58,"and Ramoth with its pasture lands, and Anem with its pasture lands:"],["1 Chronicles",6,59,"and out of the tribe of Asher; Mashal with its pasture lands, and Abdon with its pasture lands,"],["1 Chronicles",6,60,"and Hukok with its pasture lands and Rehob with its pasture lands:"],["1 Chronicles",6,61,"and out of the tribe of Naphtali, Kedesh in the Galilee with its pasture lands, and Hammon with its pasture lands, and Kirjathaim with its pasture lands."],["1 Chronicles",6,62,"To the rest of the children of Merari were given out of the tribe of Zebulun, Rimmon with its pasture lands, Tabor with its pasture lands:"],["1 Chronicles",6,63,"and on the other side of Jordan by Jericho, on the east side of the Jordan, were given them out of the tribes of Reuben, Bezer in the wilderness with its pasture lands, and Jahzah with its pasture lands,"],["1 Chronicles",6,64,"and Kedemoth with its pasture lands, and Mephaath with its pasture lands:"],["1 Chronicles",6,65,"and out of the tribe of Gad; Ramoth in the Gilead with its pasture lands, and Mahanaim with its pasture lands,"],["1 Chronicles",6,66,"and Heshbon with its pasture lands, and Jazer with its pasture lands."],["1 Chronicles",7,1,"Now the sons of Issachar were, Tola, and Puah, Jashub, and Shimron, four."],["1 Chronicles",7,2,"And the sons of Tola; Uzzi, and Rephaiah, and Jeriel, and Jahmai, and Jibsam, and Shemuel, heads of their father's houses, that is, of Tola; were valiant men at arms in their generations: their number in the days of David was twenty two thousand six hundred."],["1 Chronicles",7,3,"And the sons of Uzzi; Izrahiah: and the sons of Izrahiah; Michal, and Obadiah and Joel, Isshiah; five: all of them chief men."],["1 Chronicles",7,4,"And with them, by their generations, after the houses of their fathers, were bands of soldiers for war; thirty six thousand men: for they had many wives and sons."],["1 Chronicles",7,5,"And their brethren among all the families of Issachar, valiant men at arms, reckoned in all by their genealogies, eighty seven thousand."],["1 Chronicles",7,6,"The sons of Benjamin; Bela, and Becher, and Jediael; three."],["1 Chronicles",7,7,"And the sons of Bela; Ezbon, and Uzzi, and Uzziel, and Jerimoth, and Iri; five; heads of the houses of their fathers, mighty men at arms; and were reckoned by their genealogies, twenty two thousand and thirty four."],["1 Chronicles",7,8,"And the sons of Becher; Zemira, and Joash, and Eliezer, and Elioenai, and Omri, and Jeremoth, and Abijah, and Anathoth, and Alemeth. All these were the sons of Becher."],["1 Chronicles",7,9,"And the number of them, after their genealogy by their generations, heads of the houses of their fathers, mighty men at arms, was twenty thousand two hundred."],["1 Chronicles",7,10,"And the sons of Jediael; Bilhan: and the sons of Bilhan; Jeush, and Benjamin, and Ehud, and Chenaanah, and Zethan, and Tarshish, and Ahishahar."],["1 Chronicles",7,11,"All these were the sons of Jediael, by the heads of their fathers, mighty men at arms, seventeen thousand two hundred, fit to go out to war and battle."],["1 Chronicles",7,12,"And Shuppim, and Huppim, the children of Ir, and Hushim, the sons of Aher."],["1 Chronicles",7,13,"The sons of Naphtali; Jahziel, and Guni, and Jezer, and Shallum, the sons of Bilhah."],["1 Chronicles",7,14,"The sons of Manasseh; Asriel, whom she bore: (but his concubine, the Syrian woman, bore Machir the father of Gilead:"],["1 Chronicles",7,15,"and Machir took to wife one of the family of Huppim and Shuppim, a sister, whose name was Maachah;) and the name of the second was Zelophehad: and Zelophehad had daughters."],["1 Chronicles",7,16,"And Maachah the wife of Machir bore a son, and she called his name Peresh; and the name of his brother was Sheresh; and his sons were Ulam and Rekem."],["1 Chronicles",7,17,"And the son of Ulam; Bedan. These were the sons of Gilead, the son of Machir, the son of Manasseh."],["1 Chronicles",7,18,"And his sister Hammoleketh bore Ishod, and Abiezer, and Mahlah."],["1 Chronicles",7,19,"And the sons of Shemida were, Ahian, and Shechem, and Likhi, and Aniam."],["1 Chronicles",7,20,"And the sons of Ephraim; Shuthelah, and Bered his son, and Tahath his son, and Eladah his son, and Tahath his son,"],["1 Chronicles",7,21,"and Zabad his son, and Shuthelah his son, and Ezer, and Elead, whom the men of Gath that were born in that land slew, because they came down to take away their cattle."],["1 Chronicles",7,22,"And Ephraim their father mourned many days, and his brothers came to comfort him."],["1 Chronicles",7,23,"And he went in to his wife, and she conceived, and bore a son, and he called his name Beriah, because evil had befallen his house."],["1 Chronicles",7,24,"(And his daughter was Sherah, who built both the lower and the upper Beth-horon, and Uzzen-sherah.)"],["1 Chronicles",7,25,"And Rephah was his son, and Resheph, and Telah his son, and Tahan his son,"],["1 Chronicles",7,26,"Laadan his son, Ammihud his son, Elishama his son,"],["1 Chronicles",7,27,"Non his son, Joshua his son."],["1 Chronicles",7,28,"And their possessions and habitations were Beth-el and its hamlets, and eastward Naaran, and westward Gezer, with its hamlets; and Shechem and its hamlets, as far as Gaza and its hamlets:"],["1 Chronicles",7,29,"and by the borders of the children of Manasseh, Beth-shean and its hamlets, Taanach and its hamlets, Megiddo and its hamlets, Dor and its hamlets. In these dwelt the children of Joseph the son of Israel."],["1 Chronicles",7,30,"The sons of Asher; Jimna, and Jishba, and Jishbi, and Beriah, and Serah their sister."],["1 Chronicles",7,31,"And the sons of Beriah; Heber, and Malchiel, who is the father of Birzavith."],["1 Chronicles",7,32,"And Heber begot Japhlet, and Shomer, and Hotham, and Shua their sister."],["1 Chronicles",7,33,"And the sons of Japhlet; Pasach, and Bimhal, and Ashvath. These are the children of Japhlet."],["1 Chronicles",7,34,"And the sons of Shemer; Ahi, and Rohgah, and Hubbah, and Aram."],["1 Chronicles",7,35,"And the sons of his brother Helem; Zophah, and Jimna, and Shelesh, and Amal."],["1 Chronicles",7,36,"The sons of Zophah; Suah, and Harnepher, and Shual, and Beri, and Imrah,"],["1 Chronicles",7,37,"Bezer, and Hod, and Shammah, and Shilshah, and Ithran, and Beera."],["1 Chronicles",7,38,"And the sons of Jether; Jephunneh, and Pispah, and Ara."],["1 Chronicles",7,39,"And the sons of Ulla; Arah, and Hanniel, and Rezia."],["1 Chronicles",7,40,"All these were the children of Asher, heads of their father's houses, choice and mighty men at arms, chiefs of the princes. And the number reckoned by genealogy of those who were apt for war and battle was twenty six thousand men."],["1 Chronicles",8,1,"Now Benjamin begot Bela his firstborn. Ashbel the second, and Aharah the third,"],["1 Chronicles",8,2,"Nohah the fourth, and Raphah the fifth."],["1 Chronicles",8,3,"And the sons of Bela were, Addar, and Gera, and Abihud,"],["1 Chronicles",8,4,"and Abishua, and Naaman, and Ahoah,"],["1 Chronicles",8,5,"and Gera, and Shephuphan, and Huram."],["1 Chronicles",8,6,"And these are the sons of Ehud: these are the heads of the fathers' houses of the inhabitants of Geba, and they were exiled into Manahath:"],["1 Chronicles",8,7,"and Naaman, and Ahiah, and Gera, he exiled them, and begot Uzza, and Ahihud."],["1 Chronicles",8,8,"And Shaharaim begot children in the field of Moab, after he had sent away Hushim and Baara his wives."],["1 Chronicles",8,9,"And he begot of Hodesh his wife, Jobab, and Zibiah, and Mesha, and Malcham,"],["1 Chronicles",8,10,"And Jeuz, and Shachia, and Mirma. These were his sons, heads of the fathers' houses."],["1 Chronicles",8,11,"And of Hushim he begot Abitub, and Elpaal."],["1 Chronicles",8,12,"The sons of Elpaal; Eber, and Misham, and Shamed, who built Ono, and Lod, with its hamlets:"],["1 Chronicles",8,13,"Beriah also, and Shema, who were heads of the fathers' houses of the inhabitants of Aijalon, who drove away the inhabitants of Gath:"],["1 Chronicles",8,14,"and Ahio, Shashak, and Jeremoth,"],["1 Chronicles",8,15,"and Zebadiah, and Arad, and Eder,"],["1 Chronicles",8,16,"and Michael, and Ispah, and Joha, the sons of Beriah;"],["1 Chronicles",8,17,"and Zebadiah, and Meshullam, and Hezeki, and Heber,"],["1 Chronicles",8,18,"and Ishmerai, and Jezliah, and Jobab, the sons of Elpaal;"],["1 Chronicles",8,19,"and Jakim, and Zichri, and Zabdi,"],["1 Chronicles",8,20,"and Elienai, and Zilthai, and Eliel,"],["1 Chronicles",8,21,"and Adaiah, and Beraiah, and Shimrath, the sons of Shimei;"],["1 Chronicles",8,22,"and Ishpan, and Eber, and Eliel,"],["1 Chronicles",8,23,"and Abdon, and Zichri, and Hanan,"],["1 Chronicles",8,24,"and Hananiah, and Elam, and Antothijah,"],["1 Chronicles",8,25,"and Jifdeya, and Penuel, the sons of Shashak;"],["1 Chronicles",8,26,"and Shamsherai, and Shehariah, and Athaliah,"],["1 Chronicles",8,27,"and Jaresiah, and Elijah, and Zichri, the sons of Jeroham."],["1 Chronicles",8,28,"These were heads of the father's houses, by their generations, chief men. These dwelt in Jerusalem."],["1 Chronicles",8,29,"And at Gibeon dwelt the father of Gibeon; whose wife's name was Maachah:"],["1 Chronicles",8,30,"and his firstborn son Abdon, and Zur, and Kish, and Baal, and Nadab,"],["1 Chronicles",8,31,"and Gedor, and Ahio, and Zacher."],["1 Chronicles",8,32,"And Mikloth begot Shimea. And these also dwelt opposite their brethren in Jerusalem, with their brethren."],["1 Chronicles",8,33,"And Ner begot Kish, and Kish begot Saul, and Saul begot Jonathan, and Malchi-shua, and Abinadab, and Esh-baal."],["1 Chronicles",8,34,"And the son of Jonathan was Merib-baal; and Merib-baal begot Micah."],["1 Chronicles",8,35,"And the sons of Micah were, Pithon, and Melech, and Tarea, and Ahaz."],["1 Chronicles",8,36,"And Ahaz begot Jehoadah; and Jehoadah begot Alemeth, and Azmaveth, and Zimri; and Zimri begot Moza,"],["1 Chronicles",8,37,"and Moza begot Binea: Raphah was his son, Eleasah his son, Azel his son:"],["1 Chronicles",8,38,"and Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan. All these were the sons of Azel."],["1 Chronicles",8,39,"And the sons of Esek his brother were, Ulam his firstborn, Jeush the second, and Eliphelet the third."],["1 Chronicles",8,40,"And the sons of Ulam were mighty men at arms, archers, and had many sons, and sons' sons, a hundred and fifty. All these were of the sons of Benjamin."],["1 Chronicles",9,1,"So all Israel were reckoned by genealogies; and, behold, they were written in the book of the kings of Israel; and Judah was carried away to Babylon for their transgression."],["1 Chronicles",9,2,"Now the first inhabitants who dwelt in their possessions in their cities were, the Israelites, the priests, Levites, and the temple servants."],["1 Chronicles",9,3,"And in Jerusalem dwelt some of the children of Judah, and some of the children of Benjamin, and some of the children of Ephraim, and Manasseh;"],["1 Chronicles",9,4,"Utai the son of Ammihud, the son of Omri, the son of Imri, the son of Bani, of the children of Pharez the son of Judah."],["1 Chronicles",9,5,"And of the Shilonite; Asaiah the firstborn, and his sons."],["1 Chronicles",9,6,"And of the sons of Zerah; Jeuel, and their brethren, six hundred and ninety."],["1 Chronicles",9,7,"And of the sons of Benjamin; Sallu the son of Meshullam, the son of Hodaviah, the son of Senuah,"],["1 Chronicles",9,8,"and Ibnijah the son of Jeroham, and Elah the son of Uzzi, the son of Michri, and Meshullam the son of Shephatiah, the son of Reuel, the son of Ibnijah;"],["1 Chronicles",9,9,"and their brethren, according to their generations, nine hundred and fifty six. All these men were chiefs of the fathers in the houses of their fathers."],["1 Chronicles",9,10,"And of the priests; Jedaiah, and Jehoiarib, and Jachin,"],["1 Chronicles",9,11,"and Azariah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, the ruler of the house of God;"],["1 Chronicles",9,12,"and Adaiah the son of Jeroham, the son of Pashur, the son of Malchijah, and Maasiai the son of Adiel, the son of Jahzerah, the son of Meshullam, the son of Meshillemith, the son of Immer;"],["1 Chronicles",9,13,"and their brethren, heads of the houses of their fathers, a thousand seven hundred and sixty; very able men for the work of the service of the house of God."],["1 Chronicles",9,14,"And of the Levites; Shemaiah the son of Hashshub, the son of Azrikam, the son of Hashabiah, of the sons of Merari;"],["1 Chronicles",9,15,"and Bakbakkar, Heresh, and Galal, and Mattaniah the son of Micah, the son of Zichri, the son of Asaph;"],["1 Chronicles",9,16,"and Obadiah the son of Shemaiah, the son of Galal, the son of Jeduthun, and Berechiah the son of Asa, the son of Elkanah, who dwelt in the settlements of the Netophathites."],["1 Chronicles",9,17,"And the gatekeepers were; Shallum, and Akkub, and Talmon, and Ahiman, and their brethren: (Shallum being the chief;)"],["1 Chronicles",9,18,"who were hitherto stationed at the king's gate eastward; they were gatekeepers for the camp of the children of Levi."],["1 Chronicles",9,19,"And Shallum the son of Kore, the son of Ebiasaph, the son of Korah, and his brethren, of the house of his father, the Korahites, were over the work of the service, keepers of the threshold of the tabernacle: and their fathers, being over the camp of the Lord, were keepers of the entry."],["1 Chronicles",9,20,"And Phinehas the son of Eleazar was the ruler over them in time past, and the Lord was with him."],["1 Chronicles",9,21,"And Zechariah the son of Meshelemiah was keeper of the door of the Tent of Meeting."],["1 Chronicles",9,22,"All these who were chosen to be keepers in the thresholds were two hundred and twelve. These were reckoned by their genealogy in their settlements, whom David and Samuel the seer did establish in their office of trust."],["1 Chronicles",9,23,"So they and their children had the oversight of the gates of the house of the Lord, the house of the tabernacle, by watches."],["1 Chronicles",9,24,"On the four sides were the gatekeepers; east, west, north, and south."],["1 Chronicles",9,25,"And their brethren, who were in their settlements, were to come in every seven days from time to time to be with them."],["1 Chronicles",9,26,"For these Levites, the four chief gatekeepers, were in an office of trust, and were appointed over the chambers and treasuries of the house of God."],["1 Chronicles",9,27,"And they lodged round about the house of God, because the charge was upon them, and they had the duty of opening it every morning."],["1 Chronicles",9,28,"And certain of them had the charge of the vessels of service, that they should bring them in by number and out by number."],["1 Chronicles",9,29,"Some of them also were appointed to oversee the vessels, and all the instruments of the sanctuary, and the fine flour, and the wine, and the oil, and the frankincense, and the spices."],["1 Chronicles",9,30,"And some of the sons of the priests made the ointment of the spices."],["1 Chronicles",9,31,"And Mattithiah, one of the Levites, who was the firstborn of Shallum the Korahite, was entrusted with that which was prepared in the pans."],["1 Chronicles",9,32,"And other of their brethren, of the sons of the Kohathites, were over the showbread, to prepare it every sabbath."],["1 Chronicles",9,33,"And these were the singers, chiefs of the fathers' houses of the Levites, dwelling in the temple chambers free from other duties: for they were employed in that work day and night."],["1 Chronicles",9,34,"These were chiefs of fathers' houses of the Levites, chief men by their generations; these dwelt in Jerusalem."],["1 Chronicles",9,35,"And in Gibeon dwelt the father of Gibeon, Jeiel, whose wife's name was Maachah:"],["1 Chronicles",9,36,"and his firstborn son Abdon, then Zur, and Kish, and Baal, and Ner, and Nadab,"],["1 Chronicles",9,37,"and Gedor, and Ahio, and Zechariah, and Mikloth."],["1 Chronicles",9,38,"And Mikloth begot Shimeam. And they also dwelt opposite their brethren in Jerusalem, with their brethren."],["1 Chronicles",9,39,"And Ner begot Kish; and Kish begot Saul; and Saul begot Jonathan, and Malchi-shua, and Abinadab, and Esh-baal."],["1 Chronicles",9,40,"And the son of Jonathan was Merib-baal; and Merib-baal begot Micah."],["1 Chronicles",9,41,"And the sons of Micah were, Pithon, and Melech, and Tahrea,"],["1 Chronicles",9,42,"and Ahaz begot Jarah; and Jarah begot Alemeth, and Azmaveth, and Zimri; and Zimri begot Moza;"],["1 Chronicles",9,43,"and Moza begot Binea; and Rephaiah his son, Eleasah his son, Azel his son."],["1 Chronicles",9,44,"And Azel had six sons, whose names were these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan: these were the sons of Azel."],["1 Chronicles",10,1,"Now the Philistines fought against Israel; and the men of Israel fled from before the Philistines and fell down slain on mount Gilboa."],["1 Chronicles",10,2,"And the Philistines followed hard after Saul, and after his sons; and the Philistines slew Jonathan, and Abinadab, and Malchi-shua, the sons of Saul."],["1 Chronicles",10,3,"And the battle went hard against Saul, and the archers hit him, and he was in dread because of the archers."],["1 Chronicles",10,4,"Then Saul said to his armourbearer, Draw thy sword, and pierce me with it; lest these uncircumcised ones come and abuse me. But his armourbearer would not; for he was much afraid. So Saul took a sword, and fell upon it."],["1 Chronicles",10,5,"And when his armourbearer saw that Saul was dead, he fell likewise on the sword, and died."],["1 Chronicles",10,6,"So Saul died, and his three sons, and all his house died together."],["1 Chronicles",10,7,"And when all the men of Israel who were in the valley saw that they fled, and that Saul and his sons were dead, then they forsook their cities, and fled: and the Philistines came and dwelt in them."],["1 Chronicles",10,8,"And it came to pass on the morrow, when the Philistines came to strip the slain, that they found Saul and his sons fallen on mount Gilboa."],["1 Chronicles",10,9,"And when they had stripped him, they took his head, and his armour, and sent into the land of the Philistines round about, to carry tidings to their idols, and to the people."],["1 Chronicles",10,10,"And they put his armour in the house of their gods, and fastened his head in the temple of Dagon."],["1 Chronicles",10,11,"And when all Jabesh-gilead heard all that the Philistines had done to Saul,"],["1 Chronicles",10,12,"they arose, all the men at arms, and took away the body of Saul, and the bodies of his sons, and brought them to Jabesh, and buried their bones under the terebinth in Jabesh, and fasted seven days."],["1 Chronicles",10,13,"So Saul died for his transgression which he committed against the Lord, against the word of the Lord, which he did not keep, and also for asking counsel of a medium, to make inquiry;"],["1 Chronicles",10,14,"and he inquired not of the Lord: therefore he slew him, and turned the kingdom over to David the son of Jesse."],["1 Chronicles",11,1,"Then all Israel gathered themselves to David to Hebron, saying, Behold, we are thy bone and thy flesh."],["1 Chronicles",11,2,"And moreover in time past, even when Saul was king, thou wast he who didst lead out Israel and bring them in: and the Lord thy God said to thee, Thou shalt be shepherd over my people Israel, and thou shalt be ruler over my people Israel."],["1 Chronicles",11,3,"Therefore all the elders of Israel came to the king to Hebron; and David made a covenant with them in Hebron before the Lord; and they anointed David king over Israel, according to the word of the Lord by Samuel."],["1 Chronicles",11,4,"And David and all Israel went to Jerusalem, which is Jebus; where the Jebus were, the inhabitants of the land."],["1 Chronicles",11,5,"And the inhabitants of Jebus said to David, Thou shalt not come here. Nevertheless David took the stronghold of Zion, which is the city of David."],["1 Chronicles",11,6,"And David said, Whoever smites the Jebusite first shall be chief and captain. So Joab the son of Zeruiah went first up, and became the chief."],["1 Chronicles",11,7,"And David dwelt in the stronghold; therefore they called it the city of David."],["1 Chronicles",11,8,"And he built the city round about, even from the Millo round about: and Joab repaired the rest of the city."],["1 Chronicles",11,9,"So David grew greater and greater: for the Lord of hosts was with him."],["1 Chronicles",11,10,"These also are the chiefs of the mighty men whom David had, who held fast to him in his kingdom, together with all Israel, to make him king, according to the word of the Lord concerning Israel."],["1 Chronicles",11,11,"And this is the number of the mighty men whom David had; Jashobeam, the son of Hachmoni, the chief of the captains: he swung his spear over three hundred slain at one time."],["1 Chronicles",11,12,"And after him was Eleazar the son of Dodo, the Ahohite, who was one of the three mighty men."],["1 Chronicles",11,13,"He was with David at Pas-dammim, and there the Philistines were gathered together to battle, where there was a plot of ground full of barley; and the people fled from before the Philistines."],["1 Chronicles",11,14,"And they set themselves in the midst of that plot, and delivered it, and slew the Philistines; and the Lord saved them by a great deliverance."],["1 Chronicles",11,15,"Now three of the thirty captains went down to the rock to David, into the cave of Adullam; and the host of the Philistines encamped in the valley of Rephaim."],["1 Chronicles",11,16,"And David was then in the stronghold, and the garrison of the Philistines was then at Beth-lehem."],["1 Chronicles",11,17,"And David longed, and said, Oh that someone would give me water of the well of Beth-lehem, that is by the gate, to drink!"],["1 Chronicles",11,18,"And those three broke through the host of the Philistines, and drew water out of the well of Beth-lehem, that was by the gate, and took it, and brought it to David: but David would not drink of it, but poured it out to the Lord,"],["1 Chronicles",11,19,"and he said, far be it from me before my God, that I should do this thing: shall I drink the blood of these men that have put their lives in jeopardy? for with the jeopardy of their lives have they brought it. Therefore he would not drink it. These things did these three mightiest."],["1 Chronicles",11,20,"And Abishai the brother of Joab, he was chief among the three: and he swung his spear over three hundred slain, and had a name among the three."],["1 Chronicles",11,21,"Of the three in the second rank he was most honourable; therefore he was their captain: but he attained not to the first three."],["1 Chronicles",11,22,"Benaiah the son of Jehoiada, the son of a valiant man of Kabzeel, who had done many acts; he slew two lionhearted men of Moab: and he went down and slew a lion in a pit in a time of snow."],["1 Chronicles",11,23,"And he slew a Egyptian man, a man of great stature, five cubits high; and in the Egyptian's hand was a spear like a weaver's beam; and he went down to him with a staff, and plucked the spear out of the Egyptian's hand, and slew him with his own spear."],["1 Chronicles",11,24,"These things Benaiah the son of Jehoiada did, and he had a name among the three mighty ones."],["1 Chronicles",11,25,"Behold, he was renowned among the thirty, but did not attain to the first three: and David set him over his guard."],["1 Chronicles",11,26,"And the valiant men of the armies were Asahel the brother of Joab, Elhanan the son of Dodo of Beth-lehem,"],["1 Chronicles",11,27,"Shammoth the Harorite, Helez the Pelonite,"],["1 Chronicles",11,28,"Ira the son of Ikkesh the Tekoite, Abi-ezer the Antothite,"],["1 Chronicles",11,29,"Sibbechai the Hushathite, Ilai the Ahohite,"],["1 Chronicles",11,30,"Maharai the Netophathite, Heled the son of Baanah the Netophathite,"],["1 Chronicles",11,31,"Itai the son of Rive of Gibeah of the children of Benjamin, Benaiah the Pirathonite,"],["1 Chronicles",11,32,"Hurai of the wadis of Gaash, Abiel the Arbathite,"],["1 Chronicles",11,33,"Azmaveth the Baharumite, Eliahba the Shaalbonite,"],["1 Chronicles",11,34,"the sons of Hashem the Gizonite, Jonathan the son of Shage the Hararite,"],["1 Chronicles",11,35,"Ahiam the son of Sacar the Hararite, Eliphal the son of Ur,"],["1 Chronicles",11,36,"Hepher the Mecherathite, Ahijah the Pelonite,"],["1 Chronicles",11,37,"Hezro the Carmelite, Naarai the son of Ezbai,"],["1 Chronicles",11,38,"Joel the brother of Nathan, Mibhar the son of Haggeri,"],["1 Chronicles",11,39,"Zelek the Ammonite, Nahrai the Berothite, the armourbearer of Joab the son of Zeruiah,"],["1 Chronicles",11,40,"Ira the Ithrite, Gareb the Ithrite,"],["1 Chronicles",11,41,"Uriah the Hittite, Zabad the son of Ahlai,"],["1 Chronicles",11,42,"Adina the son of Shiza the Reubenite, a captain of the Reubenites, and thirty with him."],["1 Chronicles",11,43,"Hanan the son of Maachah, and Joshaphat the Mithnite,"],["1 Chronicles",11,44,"Uzziah the Ashterathite, Shama and Jeiel the sons of Hotham the Aroerite,"],["1 Chronicles",11,45,"Jediael the son of Shimri, and Joha his brother, the Tizite,"],["1 Chronicles",11,46,"Eliel from Mahavite, and Jeribai, and Joshaviah, the sons of Elnaam, and Jitma the Moabite,"],["1 Chronicles",11,47,"Eliel, and Obed, and Jaasiel of Mezobaia."],["1 Chronicles",12,1,"Now these are they who came to David to Ziklag, while he yet kept himself shut up because of Saul the son of Kish: and they were among the mighty men, his helpers in war."],["1 Chronicles",12,2,"They were armed with bows, and could use both the right hand and the left in slinging stones and shooting arrows from the bow; they were of Saul's brethren of Benjamin."],["1 Chronicles",12,3,"The chief was Ahiezer, then Joash, the sons of Shemaah the Gibeathite; and Jeziel, and Met, the sons of Azmaveth; and Berachah, and Jehu the Antothite,"],["1 Chronicles",12,4,"and Ishmaiah the Gibeonite, a mighty man among the thirty, and over the thirty;"],["1 Chronicles",12,5,"and Jeremiah, and Jahaziel, and Johanan, and Jozabad the Gederathite,"],["1 Chronicles",12,6,"Eluzai and Jerimoth, and Bealiah, and Shemariah, and Shephatiah the Haruphite,"],["1 Chronicles",12,7,"Elkanah, and Isshiah, and Azareel, and Joezer, and Jashobeam, the Korhites,"],["1 Chronicles",12,8,"and Joelah, and Zebadiah, the sons of Jeroham of Gedor."],["1 Chronicles",12,9,"And of the Gadites there separated themselves to David into the stronghold to the wilderness men of might, and men of war apt for battle, who could handle shield and spear, whose faces were like the faces of lions, and who were as swift as the roes upon the mountains;"],["1 Chronicles",12,10,"Ezer the first, Obadiah the second, Eliab the third,"],["1 Chronicles",12,11,"Mishmannah the fourth, Jeremiah the fifth,"],["1 Chronicles",12,12,"Attai the sixth, Eliel the seventh,"],["1 Chronicles",12,13,"Johanan the eighth, Elzabad the ninth,"],["1 Chronicles",12,14,"Jeremiah the tenth, Machbanai the eleventh."],["1 Chronicles",12,15,"These were of the sons of Gad, captains of the host: the least was over a hundred, and the greatest over a thousand."],["1 Chronicles",12,16,"These are they who went over the Jordan in the first month, when it had overflowed all its banks; and they put to flight all those of the valleys, both towards the east, and towards the west."],["1 Chronicles",12,17,"And there came of the children of Benjamin and Judah to the stronghold, to David."],["1 Chronicles",12,18,"And David went out to meet them, and answered and said to them, If you are come peaceably to me to help me, my heart shall be knit to you: but if you are come to betray me to my enemies, seeing there is no wrong in my hands, then let the God of our fathers see, and rebuke you."],["1 Chronicles",12,19,"Then the spirit came upon Amasai, who was chief of the captains, and he said, Thine are we, David, and on thy side, thou son of Jesse: peace, peace be to thee, and peace be to thy helpers; for thy God helps thee. Then David received them, and made them captains of the band."],["1 Chronicles",12,20,"And some of Manasseh deserted to David, when he came with the Philistines against Saul to battle: but they did not help them: for the lords of the Philistines took counsel and sent him away, saying, He will desert to his master Saul to the jeopardy of our heads."],["1 Chronicles",12,21,"As he went to Ziklag, there deserted to him of Manasseh, Adnah, and Jozabad, and Jediael, and Michael, and Jozabad, and Elihu, and Zilthai, captains of the thousands that were of Manasseh."],["1 Chronicles",12,22,"And they helped David against the troop of raiders: for they were all mighty men at arms, and they were captains in the host."],["1 Chronicles",12,23,"For at that time day by day men came over to David to help him, until it was a great host, like the host of God."],["1 Chronicles",12,24,"And these are the numbers of the bands of the armed troops who came to David to Hebron, to turn the kingdom of Saul over to him, according to the word of the Lord."],["1 Chronicles",12,25,"The children of Judah who bore shield and spear were six thousand eight hundred, armed troops."],["1 Chronicles",12,26,"Of the children of Simeon mighty men at arms for the war, seven thousand one hundred."],["1 Chronicles",12,27,"Of the children of Levi four thousand six hundred."],["1 Chronicles",12,28,"And Jehoiada was the leader of the house of Aaron, and with him three thousand seven hundred;"],["1 Chronicles",12,29,"and Zadok, a young mighty man at arms, and of his father's home, twenty two captains."],["1 Chronicles",12,30,"And of the children of Benjamin, the kindred of Saul, three thousand: for hitherto the greatest part of them had kept their allegiance to the house of Saul."],["1 Chronicles",12,31,"And of the children of Ephraim were twenty thousand eight hundred, mighty men at arms, famous throughout the houses of their fathers."],["1 Chronicles",12,32,"And of the half tribe of Manasseh eighteen thousand, who were expressly named, to come and make David king."],["1 Chronicles",12,33,"And of the children of Issachar, men who had understanding of the times, to know what Israel ought to do; the heads of them were two hundred; and all their brethren were at their commandment."],["1 Chronicles",12,34,"Of Zebulun, such as went out to battle, expert in war, with all weapons of war, fifty thousand; and who ranged themselves with undivided loyalty."],["1 Chronicles",12,35,"And of Naphtali a thousand captains, and with them with shield and spear thirty seven thousand."],["1 Chronicles",12,36,"And of the Danites expert in war twenty eight thousand six hundred."],["1 Chronicles",12,37,"And of Asher, such as went forth to battle, expert in war, forty thousand."],["1 Chronicles",12,38,"And on the other side of the Jordan, of the Reubenites, and the Gadites, and of the half tribe of Manasseh, with all manner of weapons of war for the battle, a hundred and twenty thousand."],["1 Chronicles",12,39,"All these men of war, ranged in battle order, came with a perfect heart to Hebron, to make David king over all Israel: and all the rest also of Israel were of one heart to make David king."],["1 Chronicles",12,40,"And there they were with David three days, eating and drinking: for their brethren had prepared for them."],["1 Chronicles",12,41,"Also their neighbours as far as Issachar and Zebulun and Naphtali, brought bread on asses, and on camels, and on mules, and on oxen, and provisions of meal, cakes of figs, and bunches of raisins, and wine, and oil, and oxen, and sheep in abundance: for there was joy in Israel."],["1 Chronicles",13,1,"And David consulted with the captains of thousands and hundreds, and with every leader."],["1 Chronicles",13,2,"And David said to all the congregation of Israel, If it seem good to you, and that it be of the Lord our God, let us send abroad to our brethren everywhere, who are left in all the land of Israel, and with them also to the priests and Levites who are in their cities that have pasture lands that they may gather themselves to us:"],["1 Chronicles",13,3,"and let us bring back the ark of our God to us: for we did not inquire at it in the days of Saul."],["1 Chronicles",13,4,"And all the congregation said that they would do so: for the thing seemed right in the eyes of all the people."],["1 Chronicles",13,5,"So David gathered all Israel together, from Shihor of Egypt as far as the entrance of Hamath, to bring the ark of God from Kirjath-jearim."],["1 Chronicles",13,6,"And David went up, and all Israel to Baalah, that is, to Kirjath-jearim, which belonged to Judah, to bring up from there the ark of God the Lord, who dwells above the keruvim, by whose name it is called."],["1 Chronicles",13,7,"And they carried the ark of God in a new cart out of the house of Abinadab: and Uzza and Ahio drove the cart."],["1 Chronicles",13,8,"And David and all Israel played before God with all their might, and with singing, and with lyres, and with lutes, and with timbrels, and with cymbals, and with trumpets."],["1 Chronicles",13,9,"And when they came to the threshing floor of Chidon, Uzza put out his hand to hold the ark; for the oxen shook it."],["1 Chronicles",13,10,"And the anger of the Lord burned against Uzza, and he smote him, because he put his hand to the ark: and there he died before God."],["1 Chronicles",13,11,"And David was vexed, because the Lord had broken out upon Uzza: so that place is called Perez-uzza to this day."],["1 Chronicles",13,12,"And David was afraid of God that day, saying, How shall I bring the ark of God home to me?"],["1 Chronicles",13,13,"So David did not bring the ark to himself to the city of David, but carried it aside into the house of Obed-edom the Gittite."],["1 Chronicles",13,14,"And the ark of God remained with the family of Obed-edom in his house for three months. And the Lord blessed the house of Obed-edom and all that he had."],["1 Chronicles",14,1,"Now Huram king of Tyre sent messengers to David, and timber of cedars, with masons and carpenters, to build him a house."],["1 Chronicles",14,2,"And David perceived that the Lord had confirmed him king over Israel, for his kingdom was highly exalted, for the sake of his people Israel."],["1 Chronicles",14,3,"And David took more wives at Jerusalem: and David begot more sons and daughters."],["1 Chronicles",14,4,"Now these are the names of his children whom he had in Jerusalem; Shammua, and Shobab, Nathan, and Solomon,"],["1 Chronicles",14,5,"and Ibhar, and Elishua, and Elpalet,"],["1 Chronicles",14,6,"and Nogah, and Nepheg, and Japhia,"],["1 Chronicles",14,7,"and Elishama, and Beeliada, and Eliphalet."],["1 Chronicles",14,8,"And when the Philistines heard that David was anointed king over all Israel, all the Philistines went up to seek David. And David heard of it, and went out against them."],["1 Chronicles",14,9,"And the Philistines came and made a raid in the valley of Rephaim."],["1 Chronicles",14,10,"And David inquired of God, saying, Shall I go up against the Philistines? and wilt Thou deliver them into my hand? And the Lord said to him, Go up; for I will deliver them into thy hand."],["1 Chronicles",14,11,"So they came up to Baal-perazim; and David smote them there. Then David said, God has broken through my enemies by my hand like a bursting flood of waters: therefore they called the name of that place Baal-perazim."],["1 Chronicles",14,12,"And they left their gods there and David gave command, that they should be burned with fire."],["1 Chronicles",14,13,"And the Philistines once again made a raid in the valley."],["1 Chronicles",14,14,"So David inquired again of God; and God said to him, Do not go up after them; turn away from them, and come upon them opposite the bakha trees."],["1 Chronicles",14,15,"And let it be, when thou shalt hear a sound of marching in the tops of the bakha trees, then thou shalt go out to battle: for God has gone out before thee to smite the camp of the Philistines."],["1 Chronicles",14,16,"David therefore did as God commanded him: and they smote the camp of the Philistines from Gibeon as far as Gezer."],["1 Chronicles",14,17,"And David's renown went out into all the lands; and the Lord brought the fear of him upon all nations."],["1 Chronicles",15,1,"And David made houses for himself in the city of David, and prepared a place for the ark of God, and pitched for it a tent."],["1 Chronicles",15,2,"Then David said, None ought to carry the ark of God but the Levites: for the Lord has chosen them to carry the ark of God, and to minister to him forever."],["1 Chronicles",15,3,"And David gathered all Israel together to Jerusalem, to bring up the ark of the Lord to its place, which he had prepared for it."],["1 Chronicles",15,4,"And David assembled the children of Aaron, and the Levites:"],["1 Chronicles",15,5,"of the sons of Kohath; Uriel the chief, and his brethren a hundred and twenty:"],["1 Chronicles",15,6,"of the sons of Merari; Asaiah the chief, and his brethren two hundred and twenty:"],["1 Chronicles",15,7,"of the sons of Gershom: Joel the chief, and his brethren a hundred and thirty:"],["1 Chronicles",15,8,"of the sons of Elizaphan; Shemaiah the chief, and his brethren two hundred:"],["1 Chronicles",15,9,"of the sons of Hebron; Eliel the chief, and his brethren eighty:"],["1 Chronicles",15,10,"of the sons of Uzziel; Amminadab the chief, and his brethren a hundred and twelve."],["1 Chronicles",15,11,"And David called for Zadok and Abiathar the priests, and for the Levites, for Uriel, Asaiah, and Joel, Shemaiah, and Eliel, and Amminadab,"],["1 Chronicles",15,12,"and he said to them, You are the chiefs of the fathers' houses of the Levites: sanctify yourselves, you and your brethren, that you may bring up the ark of the Lord God of Israel to the place that I have prepared for it."],["1 Chronicles",15,13,"For because you did not do so at first, the Lord our God made a breach upon us, because we did not seek him according to the prescribed form."],["1 Chronicles",15,14,"So the priests and the Levites sanctified themselves to bring up the ark of the Lord God of Israel."],["1 Chronicles",15,15,"And the children of the Levites bore the ark of God upon their shoulders the bars being upon them, as Moses had commanded according to the word of the Lord."],["1 Chronicles",15,16,"And David spoke to the chiefs of the Levites to appoint their brethren to be the singers with instruments of music, lutes and lyres and cymbals, playing loudly to raise sounds of joy."],["1 Chronicles",15,17,"So the Levites appointed Heman the son of Joel; and of his brethren, Asaph the son of Berechiah; and of the sons of Merari their brethren, Ethan the son of Kushaiah;"],["1 Chronicles",15,18,"and with them their brethren of the second degree, Zechariah, Ben, and Jaaziel, and Shemiramoth, and Jehiel, and Unni, Eliab, and Benaiah, and Maaseiah, and Mattithiah, and Elipheleh, and Mikneiah, and Obed-edom, and Jeiel, the gatekeepers."],["1 Chronicles",15,19,"So the singers, Heman, Asaph, and Ethan, were appointed to sound with cymbals of brass;"],["1 Chronicles",15,20,"and Zechariah, and Aziel, and Shemiramoth, and Jehiel, and Unni, and Eliab, and Maaseiah, and Benaiah, with lutes to Alamoth;"],["1 Chronicles",15,21,"and Mattithiah, and Elipheleh, and Mikneiah, and Obed-edom, and Jeiel, and Azaziah, with lyres to the Sheminith to lead."],["1 Chronicles",15,22,"And Chenaniah, chief of the Levites, was over the song: he was master in the song, because he was skilful."],["1 Chronicles",15,23,"And Berechiah and Elkanah were gatekeepers for the ark."],["1 Chronicles",15,24,"And Shebaniah, and Joshaphat, and Nethaneel, and Amasai, and Zechariah, and Benaiah, and Eliezer, the priests, did blow on the trumpets before the ark of God: and Obed-edom and Jehiah were gatekeepers for the ark."],["1 Chronicles",15,25,"So David, and the elders of Israel, and the captains over the thousands, went to bring up the ark of the covenant of the Lord out of the house of Obed-edom with joy."],["1 Chronicles",15,26,"And it came to pass, when God helped the Levites who bore the ark of the covenant of the Lord, that they offered seven bullocks and seven rams."],["1 Chronicles",15,27,"And David was clothed with a robe of fine linen, and all the Levites who bore the ark, and the singers, and Chenaniah the master of the song with the singers: David also had upon him an efod of linen."],["1 Chronicles",15,28,"Thus all Israel brought up the ark of the covenant of the Lord with shouting, and with the sound of the shofar, and with trumpets, and with cymbals, making a noise with lutes and lyres."],["1 Chronicles",15,29,"And it came to pass, as the ark of the covenant of the Lord came to the city of David, that Michal the daughter of Saul looking through a window saw king David dancing and playing: and she despised him in her heart."],["1 Chronicles",16,1,"So they brought the ark of God, and set it in the midst of the tent that David had set up for it: and they offered burnt sacrifices and peace offerings before God."],["1 Chronicles",16,2,"And when David had made an end of offering the burnt offerings and the peace offerings, he blessed the people in the name of the Lord."],["1 Chronicles",16,3,"And he distributed to every one of Israel both men and women, to every one a loaf of bread, and a good piece of meat, and a cake of raisins."],["1 Chronicles",16,4,"And he appointed certain of the Levites to minister before the ark of the Lord, and to invoke and to thank and praise the Lord God of Israel."],["1 Chronicles",16,5,"Asaph the chief, and next to him Zechariah, Jeiel, and Shemiramoth, and Jehiel, and Mattithiah, and Eliab, and Benaiah, and Obed-edom: and Jeiel with lutes and with lyres; but Asaph was to sound the cymbals;"],["1 Chronicles",16,6,"and Benaiah and Jahaziel the priests with trumpets continually before the ark of the covenant of God."],["1 Chronicles",16,7,"Then on that day David first delivered this psalm (to thank the Lord) into the hand of Asaph and his brethren."],["1 Chronicles",16,8,"Give thanks to the Lord, call upon his name, make known his deeds among the peoples."],["1 Chronicles",16,9,"Sing to him, sing psalms to him, talk of all his wondrous works."],["1 Chronicles",16,10,"Glory in his holy name: let the heart of those who seek the Lord rejoice."],["1 Chronicles",16,11,"Seek the Lord and his strength, seek his face continually."],["1 Chronicles",16,12,"Remember his marvellous works that he has done, his wonders, and the judgments of his mouth;"],["1 Chronicles",16,13,"O seed of Israel his servant, you children of Jacob, his chosen ones."],["1 Chronicles",16,14,"He is the Lord our God; his judgments are on all the earth."],["1 Chronicles",16,15,"Be mindful always of his covenant; the word which he commanded to a thousand generations;"],["1 Chronicles",16,16,"which he made with Abraham, and of his oath to Isaac;"],["1 Chronicles",16,17,"and he confirmed the same to Jacob for a law, and to Israel for an everlasting covenant,"],["1 Chronicles",16,18,"saying, To thee will I give the land of Canaan, the lot of your inheritance;"],["1 Chronicles",16,19,"when you were but a few men in number, of little account and sojourners there:"],["1 Chronicles",16,20,"when they went from nation to nation, and from one kingdom to another people;"],["1 Chronicles",16,21,"he suffered no man to do them wrong: but he reproved kings for their sakes, saying,"],["1 Chronicles",16,22,"Do not touch any anointed, and do my prophets no harm."],["1 Chronicles",16,23,"Sing to the Lord, all the earth; announce his salvation from day to day."],["1 Chronicles",16,24,"Declare his glory among the nations; his marvellous works among all peoples."],["1 Chronicles",16,25,"For great is the Lord, and greatly to be praised: and he is to be feared above all gods."],["1 Chronicles",16,26,"For all the gods of the peoples are idols: but the Lord made the heavens."],["1 Chronicles",16,27,"Honour and majesty are before him; strength and gladness are in his place."],["1 Chronicles",16,28,"Ascribe to the Lord, you families of the peoples, ascribe to the Lord glory and strength."],["1 Chronicles",16,29,"Ascribe to the Lord the glory due to his name: bring an offering, and come before him: worship the Lord in the beauty of holiness."],["1 Chronicles",16,30,"Tremble before him, all the earth: the world also is established, so that it shall not be moved."],["1 Chronicles",16,31,"Let the heavens be glad, and let the earth rejoice: and let it be said among the nations, The Lord reigns."],["1 Chronicles",16,32,"Let the sea roar, and the fulness thereof: let the field rejoice, and all that is in it."],["1 Chronicles",16,33,"Then shall the trees of the wood sing for joy at the presence of the Lord, because he comes to judge the earth."],["1 Chronicles",16,34,"O give thanks to the Lord; for he is good; for his steadfast love endures forever."],["1 Chronicles",16,35,"And say, Save us, O God of our salvation, and gather us together, and deliver us from the nations, that we may give thanks to Thy holy name, and glory in Thy praise."],["1 Chronicles",16,36,"Blessed be the Lord God of Israel for ever and ever. And all the people said, Amen, and praised the Lord."],["1 Chronicles",16,37,"So he left there before the ark of the covenant of the Lord Asaph and his brethren, to minister before the ark continually, as every day's work required:"],["1 Chronicles",16,38,"and Obed-edom with their brethren, sixty eight; and Obed-edom the son of Jeduthun and Hosah to be doorkeepers:"],["1 Chronicles",16,39,"and Zadok the priest, and his brethren the priests, before the tabernacle of the Lord in the high place that was at Gibeon,"],["1 Chronicles",16,40,"to offer burnt offerings to the Lord upon the altar of the burnt offering continually morning and evening, and to do according to all that is written in the law of the Lord, which he commanded Israel;"],["1 Chronicles",16,41,"And with them Heman and Jeduthun, and the rest who were chosen, who were expressly named, to give thanks to the Lord, because his steadfast love endures forever;"],["1 Chronicles",16,42,"and with them Heman and Jeduthun with trumpets and cymbals for making a loud sound, and with musical instruments of God. And the sons of Jeduthun were posted at the gate."],["1 Chronicles",16,43,"And all the people departed every man to his house: and David returned to bless his house."],["1 Chronicles",17,1,"Now it came to pass, as David sat in his house, that David said to Nathan the prophet, Lo, I dwell in a house of cedar wood, but the ark of the covenant of the Lord remains under curtains."],["1 Chronicles",17,2,"Then Nathan said to David, Do all that is in thy heart; for God is with thee."],["1 Chronicles",17,3,"And it came to pass the same night, that the word of God came to Nathan, saying,"],["1 Chronicles",17,4,"Go and tell David my servant, Thus says the Lord, Thou shalt not build me a house to dwell in:"],["1 Chronicles",17,5,"for I have not dwelt in a house since the day that I brought up Israel to this day; but have gone from tent to tent, and from one tabernacle to another."],["1 Chronicles",17,6,"Everywhere where I have walked among all Israel, did I speak a word to any of the judges of Israel whom I commanded to be shepherds to my people, saying, Why have you not built me a house of cedar wood?"],["1 Chronicles",17,7,"Now therefore thus shalt thou say to my servant David, Thus says the Lord of hosts, I took thee from the pasture, from following the sheep, that thou shouldst be ruler over my people Israel:"],["1 Chronicles",17,8,"and I have been with thee wherever thou hast walked, and have cut off all thy enemies from before thee, and have made thee a name like the name of the great men who are on the earth."],["1 Chronicles",17,9,"And I will ordain a place for my people Israel, and I will plant them, and they shall dwell in their place, and shall be moved no more; nor shall the children of wickedness waste them any more, as at the beginning,"],["1 Chronicles",17,10,"and ever since the time when I commanded judges to be over my people Israel. And I will subdue all thy enemies. Moreover I declare to thee that the Lord will build thee a house."],["1 Chronicles",17,11,"And it shall come to pass, when thy days are fulfilled when thou must go to be with thy fathers, that I will raise up thy seed after thee, who shall be of thy sons; and I will establish his kingdom."],["1 Chronicles",17,12,"He shall build me a house, and I will establish his throne for ever."],["1 Chronicles",17,13,"I will be his father, and he will be my son: and I will not take my steadfast love away from him, as I took it from the one who was before thee:"],["1 Chronicles",17,14,"but I will settle him in my house and in my kingdom forever: and his throne shall be established for evermore."],["1 Chronicles",17,15,"According to all these words, and according to all this vision, did Nathan speak to David."],["1 Chronicles",17,16,"And David the king came and sat before the Lord, and said, Who am I, O Lord God, and what is my house, that Thou hast brought me so far?"],["1 Chronicles",17,17,"And as though this was too little in Thy eyes, O God, Thou hast also spoken of Thy servant's house for a great while to come, and hast regarded me as a man of high degree, O Lord God."],["1 Chronicles",17,18,"What more can David say to Thee concerning the honour done to Thy servant? for Thou knowst Thy servant."],["1 Chronicles",17,19,"O Lord, for Thy servant's sake, and according to Thy own heart, hast Thou done all this greatness, in making known all these great things."],["1 Chronicles",17,20,"O Lord, there is none like Thee, nor is there any God besides Thee, according to all that we have heard with our ears."],["1 Chronicles",17,21,"And who is like Thy people Israel, a singular nation on the earth, whom God went to redeem to be his own people, to make Thee a name of greatness and awesomeness, by driving out nations from before Thy people, whom Thou didst redeem out of Egypt?"],["1 Chronicles",17,22,"For Thy people Israel didst Thou make Thy own people forever; and Thou, Lord, didst become their God."],["1 Chronicles",17,23,"Therefore now, Lord, let the thing that Thou hast spoken concerning Thy servant and concerning his house be established forever, and do as Thou hast said,"],["1 Chronicles",17,24,"So let it be established, that Thy name may be magnified forever, saying, The Lord of hosts, the God of Israel, is a God to Israel: and let the house of David Thy servant be established before Thee."],["1 Chronicles",17,25,"For Thou, O my God, hast told Thy servant that Thou wilt build him a house: therefore Thy servant has found in his heart to pray before Thee."],["1 Chronicles",17,26,"And now, Lord, Thou art God, and hast promised this goodness to Thy servant:"],["1 Chronicles",17,27,"and now it has pleased Thee to bless the house of Thy servant, that it may be before Thee forever: for Thou, O Lord, hast blessed it, and it shall be blessed forever."],["1 Chronicles",18,1,"Now after this it came to pass, that David smote the Philistines, and subdued them, and took Gath and its hamlets out of the hand of the Philistines."],["1 Chronicles",18,2,"And he smote Moab; and Moab became David's servants, and brought tribute."],["1 Chronicles",18,3,"And David smote Hadarezer king of Zobah as far as Hamath, as he went to set up his dominion by the river Euphrates."],["1 Chronicles",18,4,"And David took from him one thousand chariots, and seven thousand horsemen, and twenty thousand footmen: and David lamed all the chariot horses, but reserved from them enough for a hundred chariots."],["1 Chronicles",18,5,"And when Syria of Damascus came to help Hadarezer king of Zobah, David slew of Syria twenty two thousand men."],["1 Chronicles",18,6,"Then David put garrisons in Syria of Damascus; and the people of Syria became David's servants, and brought tribute. Thus the Lord preserved David wherever he went."],["1 Chronicles",18,7,"And David took the shields of gold that were on the servants of Hadarezer, and brought them to Jerusalem."],["1 Chronicles",18,8,"Likewise from Tibhath, and from Chun, cities of Hadarezer, David took very much brass, with which Solomon made the brazen sea, and the pillars, and the vessels of brass."],["1 Chronicles",18,9,"Now when Tou king of Hamath heard how David had smitten all the host of Hadarezer king of Zobah;"],["1 Chronicles",18,10,"he sent Hadoram his son to king David, to inquire of his welfare, and to congratulate him, because he had fought against Hadarezer, and smitten him; (for Hadarezer had wars with Tou;) and he had with him all manner of vessels of gold and silver and brass."],["1 Chronicles",18,11,"These also did king David dedicate to the Lord, with the silver and the gold that he carried away from all these nations; from Edom, and from Moab, and from the children of Ammon, and from the Philistines, and from Amalek."],["1 Chronicles",18,12,"Moreover Abishai the son of Zeruiah slew of Edom in the valley of salt eighteen thousand."],["1 Chronicles",18,13,"And he put garrisons in Edom; and all Edom became David's servants. Thus the Lord preserved David wherever he went."],["1 Chronicles",18,14,"So David reigned over all Israel, and executed judgment and justice among all his people."],["1 Chronicles",18,15,"And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud, was recorder."],["1 Chronicles",18,16,"And Zadok the son of Ahitub, and Abimelech the son of Abiathar, were the priests; and Shavsha was scribe;"],["1 Chronicles",18,17,"and Benaiah the son of Jehoiada was over the Cherethites and the Pelethites; and the sons of David were chief ministers about the king."],["1 Chronicles",19,1,"Now it came to pass after this, that Nahash the king of the children of Ammon died, and his son reigned in his stead."],["1 Chronicles",19,2,"And David said, I will deal loyally with Hanun the son of Nahash, because his father dealt loyally with me. And David sent messengers to comfort him concerning his father. So the servants of David came into the land of the children of Ammon to Hanun, to comfort him."],["1 Chronicles",19,3,"But the princes of the children of Ammon said to Hanun, Thinkest thou that David honours thy father, that he has sent comforters to thee? are not his servants come to thee to search, and to overthrow, and to spy out the land?"],["1 Chronicles",19,4,"So Hanun took David's servants, and shaved them, and cut off their garments in the middle to their hips, and sent them away."],["1 Chronicles",19,5,"Then there went certain persons, and told David how the men had been treated. And he sent to meet them: for the men were greatly ashamed. And the king said, Tarry at Jericho until your beards are grown, and then return."],["1 Chronicles",19,6,"And when the children of Ammon saw that they had made themselves odious to David, Hanun and the children of Ammon sent a thousand talents of silver to hire for themselves chariots and horsemen out of Mesopotamia, and out of Syria-maachah, and out of Zobah."],["1 Chronicles",19,7,"So they hired thirty two thousand chariots, and the king of Maachah and his people; who came and encamped before Medeba. And the children of Ammon gathered themselves together from their cities, and came to battle."],["1 Chronicles",19,8,"And when David heard of it, he sent Joab, and all the host of the mighty men."],["1 Chronicles",19,9,"And the children of Ammon came out, and ranged themselves in battle before the gate of the city: and the kings that were come were by themselves in the field."],["1 Chronicles",19,10,"Now when Joab saw that the battle was set against him before and behind, he chose out of all the choice men of Israel, and ranged them against Syria."],["1 Chronicles",19,11,"And the rest of the people he delivered into the hand of Abishai his brother, and they ranged themselves against the children of Ammon."],["1 Chronicles",19,12,"And he said, If Syria is too strong for me, then thou shalt help me: but if the children of Ammon are too strong for thee, then I will help thee."],["1 Chronicles",19,13,"Be of good courage, and let us prove strong for our people, and for the cities of our God: and let the Lord do that which is good in his sight:"],["1 Chronicles",19,14,"So Joab and the people that were with him drew near before Syria to the battle; and they fled before him."],["1 Chronicles",19,15,"And when the children of Ammon saw that Syria had fled, they likewise fled before Abishai his brother, and entered the city. Then Joab came to Jerusalem."],["1 Chronicles",19,16,"And when Syria saw that they were put to the worse before Israel, they sent messengers, and brought out the men of Syria who were beyond the river: and Shophach the captain of the host of Hadarezer went before them."],["1 Chronicles",19,17,"And it was told David; and he gathered all Israel, and passed over the Jordan, and came upon them, and ranged himself against them. So David put the battle in array against Syria, and they fought with him."],["1 Chronicles",19,18,"But Syria fled before Israel; and David slew of Syria seven thousand charioteers, and forty thousand footmen, and killed Shophach the captain of the host."],["1 Chronicles",19,19,"And when the servants of Hadarezer saw that they were put to the worse before Israel, they made peace with David, and became his servants: and Syria was not willing to help the children of Ammon any more."],["1 Chronicles",20,1,"And it came to pass, at the time of the return of the year, at the time when the kings go out to battle, that Joab led forth the power of the army, and ravaged the country of the children of Ammon, and came and besieged Rabbah. But David remained at Jerusalem. And Joab smote Rabbah, and destroyed it."],["1 Chronicles",20,2,"And David took the crown of their king from off his head, and found it to weigh a talent of gold, and there were precious stones in it; and it was set upon David's head: and he also brought very much spoil out of the city."],["1 Chronicles",20,3,"And he brought out the people who were in it, and set them to work with saws, and with harrows of iron, and with axes. Even so did David deal with all the cities of the children of Ammon. And David and all the people returned to Jerusalem."],["1 Chronicles",20,4,"And it came to pass after this that there arose war at Gezer with the Philistines; at which time Sibbechai the Hushathite slew Sippai, that was of the children of the Raphah; and they were subdued."],["1 Chronicles",20,5,"And there was war again with the Philistines; and Elhanan the son of Jair slew Lahmi the brother of Goliath the Gittite, the staff of whose spear was like a weaver's beam."],["1 Chronicles",20,6,"And yet again there was war at Gath, where there was a man of great stature, whose fingers and toes were twenty four, six on each hand, and six on each foot: and he also was the son of the Raphah."],["1 Chronicles",20,7,"And he insulted Israel, so Jonathan the son of Shimea, David's brother, slew him."],["1 Chronicles",20,8,"These were born to the Raphah in Gath; and they fell by the hand of David, and by the hand of his servants."],["1 Chronicles",21,1,"And an adversary angel stood up against Israel, and provoked David to number Israel."],["1 Chronicles",21,2,"And David said to Joab and to the rulers of the people, Go, number Israel from Beer-sheba to Dan; and bring the number of them to me, that I may know it."],["1 Chronicles",21,3,"And Joab answered, The Lord make his people a hundred times so many more as they are: but, my lord the king, are they not all my lord's servants? why then does my lord require this thing? why will he be a cause of trespass to Israel?"],["1 Chronicles",21,4,"But the king's word prevailed against Joab. So Joab departed, and went throughout all Israel, and came to Jerusalem."],["1 Chronicles",21,5,"And Joab gave the sum of the number of the people to David. In all Israel there were one million one hundred thousand men that drew sword: and Judah was four hundred and seventy thousand men that drew sword."],["1 Chronicles",21,6,"But he did not count Levi and Benjamin among them: for the king's word was abhorrent to Joab."],["1 Chronicles",21,7,"And God was displeased with this thing; therefore he smote Israel."],["1 Chronicles",21,8,"And David said to God, I have sinned greatly, because I have done this thing: but now, I pray thee, take away the iniquity of Thy servant; for I have done very foolishly."],["1 Chronicles",21,9,"And the Lord spoke to Gad, David's seer, saying,"],["1 Chronicles",21,10,"Go and tell David, saying, Thus says the Lord, I offer thee three things: choose one of them, that I may do it to thee."],["1 Chronicles",21,11,"So Gad came to David, and said to him, Thus say the Lord, Choose,"],["1 Chronicles",21,12,"either three years famine; or three months to be driven away before thy foes, while the sword of thy enemies overtakes thee; or else three days of the Lord's sword, namely, pestilence in the land, and the angel of the Lord destroying throughout all the border of Israel. Now therefore consider what word I shall bring back to him who sent me."],["1 Chronicles",21,13,"And David said to Gad, I am in great distress: let me fall rather into the hand of the Lord; for very great are his mercies: but let me not fall into the hand of man."],["1 Chronicles",21,14,"So the Lord sent a plague upon Israel: and there fell of Israel seventy thousand men."],["1 Chronicles",21,15,"And God sent an angel to Jerusalem to destroy it: and as he was about to destroy, the Lord beheld, and he relented of the evil, and said to the angel that destroyed, It is enough, now hold thy hand. And the angel of the Lord stood by the threshing floor of Ornan the Jebusite."],["1 Chronicles",21,16,"And David lifted up his eyes, and saw the angel of the Lord standing between the earth and the heaven, with a drawn sword in his hand stretched out over Jerusalem. Then David and the elders, who were clothed in sackcloth, fell upon their faces."],["1 Chronicles",21,17,"And David said to God, Is it not I who commanded the people to be numbered? so that it is I who have sinned and done very wickedly; but as for these sheep, what have they done? let Thy hand, I pray Thee, O Lord my God, be on me, and on my father's house; but not on Thy people, that they should be plagued."],["1 Chronicles",21,18,"Then the angel of the Lord commanded Gad to say to David, that David should go up, and set up an altar to the Lord on the threshing floor of Ornan the Jebusite."],["1 Chronicles",21,19,"And David went up at the saying of Gad, which he spoke in the name of the Lord."],["1 Chronicles",21,20,"And Ornan turned back, and saw the angel; and his four sons with him hid themselves. Now Ornan was threshing wheat."],["1 Chronicles",21,21,"And as David came to Ornan, Ornan looked and saw David, and went out of the threshing floor, and bowed himself to David with his face to the ground."],["1 Chronicles",21,22,"Then David said to Ornan, Grant me the place of this threshing floor, that I may build an altar on it to the Lord: thou shalt give it me for the full price: that the plague may be stayed from the people."],["1 Chronicles",21,23,"And Ornan said to David, Take it to thee, and let my lord the king do that which is good in his eyes: lo, I give thee the oxen also for burnt offerings, and the threshing instruments for wood, and the wheat for the meal offering; I give it all."],["1 Chronicles",21,24,"And king David said to Ornan, No; but I will surely buy it for the full price: for I will not take that which is thine for the Lord, nor offer burnt offerings without payment."],["1 Chronicles",21,25,"So David gave to Ornan for the place six hundred shekels of gold by weight."],["1 Chronicles",21,26,"And David built there an altar to the Lord, and offered burnt offerings and peace offerings, and called upon the Lord; and he answered him from heaven by fire upon the altar of burnt offering."],["1 Chronicles",21,27,"And the Lord commanded the angel; and he put up his sword again into its sheath."],["1 Chronicles",21,28,"At that time when David saw that the Lord had answered him on the threshing floor of Ornan the Jebusite, then he sacrificed there."],["1 Chronicles",21,29,"But the tabernacle of the Lord, which Moses made in the wilderness, and the altar of the burnt offering, were at that time in the high place at Gibeon."],["1 Chronicles",21,30,"And David could not go before it to inquire of God: for he was terrified because of the sword of the angel of the Lord."],["1 Chronicles",22,1,"Then David said, This is the house of the Lord God, and this is the altar of the burnt offering for Israel."],["1 Chronicles",22,2,"And David commanded to gather together the strangers who were in the land of Israel and he set masons to hew dressed stones to build the house of God."],["1 Chronicles",22,3,"And David prepared iron in abundance for the nails for the doors of the gates, and for the joinings; and brass in abundance without weight;"],["1 Chronicles",22,4,"and cedar trees in abundance: for the men of Zidon and of Tyre brought much cedar wood to David."],["1 Chronicles",22,5,"And David said, Solomon my son is young and tender, and the house that is to be built for the Lord must be exceedingly magnificent, of fame and of glory throughout all lands: I will therefore now make preparation for it. So David provided abundant materials before his death."],["1 Chronicles",22,6,"Then he called for Solomon his son, and charged him to build a house for the Lord God of Israel."],["1 Chronicles",22,7,"And David said to Solomon, My son, as for me, it was in my mind to build a house to the name of the Lord my God:"],["1 Chronicles",22,8,"but the word of the Lord came to me, saying, Thou hast shed blood abundantly, and hast made great wars: thou shalt not build a house to my name, because thou hast shed much blood upon the earth in my sight."],["1 Chronicles",22,9,"Behold, a son shall be born to thee, who shall be a man of tranquillity; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness to Israel in his days."],["1 Chronicles",22,10,"He shall build a house for my name; and he shall be my son, and I will be his father; and I will establish the throne of his kingdom over Israel forever."],["1 Chronicles",22,11,"Now, my son, the Lord be with thee; and prosper thou, and build the house of the Lord thy God, as he has said of thee,"],["1 Chronicles",22,12,"Only the Lord give thee wisdom and understanding, and give thee charge over Israel that thou mayst keep the law of the Lord thy God."],["1 Chronicles",22,13,"Then shalt thou prosper, if thou takest heed to fulfil the statutes and judgments which the Lord commanded Moses for Israel: be strong, and of good courage; do not dread, or be dismayed."],["1 Chronicles",22,14,"Now, behold, in my trouble I have prepared for the house of the Lord a hundred thousand talents of gold, and a million talents of silver; and brass and iron without weight; for it is in abundance: and timber and stone have I prepared; and thou mayst add to it."],["1 Chronicles",22,15,"Moreover there are workmen with thee in abundance, hewers and workers of stone and timber, and all manner of skilful men for every manner of work."],["1 Chronicles",22,16,"Of the gold, the silver, and the brass, and the iron, there is no account. Arise therefore, and be doing, and the Lord be with thee."],["1 Chronicles",22,17,"And David commanded all the princes of Israel to help Solomon his son, saying,"],["1 Chronicles",22,18,"Is not the Lord your God with you? and has he not given you rest on every side? for he has given the inhabitants of the land into my hand; and the land is subdued before the Lord, and before his people."],["1 Chronicles",22,19,"Now set your heart and your soul to seek the Lord your God; arise therefore, and build the sanctuary of the Lord God, to bring the ark of the covenant of the Lord, and the holy vessels of God, into the house that is to be built to the name of the Lord."],["1 Chronicles",23,1,"So when David was old and full of days, he made Solomon his son king over Israel."],["1 Chronicles",23,2,"And he gathered together all the princes of Israel, with the priests and the Levites."],["1 Chronicles",23,3,"Now the Levites were numbered from the age of thirty years and upwards: and their number by their polls, man by man, was thirty eight thousand."],["1 Chronicles",23,4,"Twenty four thousand of these were to oversee the work of the house of the Lord; and six thousand were officers and judges:"],["1 Chronicles",23,5,"and four thousand were gatekeepers; and four thousand praised the Lord with the instruments which I made for praise."],["1 Chronicles",23,6,"And David divided them into sections according to the sons of Levi; Gershon, Kohath, and Merari."],["1 Chronicles",23,7,"Of the Gershonites there were: Laadan, and Shimei."],["1 Chronicles",23,8,"The sons of Laadan; the chief was Jehiel, and Zetham, and Joel three."],["1 Chronicles",23,9,"The sons of Shimei; Shelomith, and Haziel, and Haran; three. These were the chiefs of the fathers' houses of Laadan."],["1 Chronicles",23,10,"And the sons of Shimei were, Jahath, Zina, and Jeush, and Beriah. These four were the sons of Shimei."],["1 Chronicles",23,11,"And Jahath was the chief, and Ziza the second: but Jeush and Beriah had not many sons; therefore they became a father's house in one reckoning."],["1 Chronicles",23,12,"The sons of Kohath; Amram, Izhar, Hebron, and Uzziel; four."],["1 Chronicles",23,13,"The sons of Amram; Aaron and Moses: and Aaron was separated, that he should be sanctified as most holy, he and his sons forever, to burn incense before the Lord, to minister to him, and to bless in his name forever."],["1 Chronicles",23,14,"Now concerning Moses the man of God, his sons were named of the tribe of Levi."],["1 Chronicles",23,15,"The sons of Moses were, Gershom, and Eliezer."],["1 Chronicles",23,16,"Of the sons of Gershom, Shebuel was the chief."],["1 Chronicles",23,17,"And the sons of Eliezer were, Rehabiah the chief. And Eliezer had no other sons; but the sons of Rehabiah were very many."],["1 Chronicles",23,18,"Of the sons of Izhar; Shelomith the chief."],["1 Chronicles",23,19,"Of the sons of Hebron; Jeriah the first, Amariah the second, Jahaziel the third, and Jekameam the fourth."],["1 Chronicles",23,20,"Of the sons of Uzziel; Micah the first, and Isshiah the second."],["1 Chronicles",23,21,"The sons of Merari; Mahli, and Mushi. The sons of Mahli; Eleazar, and Kish."],["1 Chronicles",23,22,"And Eleazar died, and had no sons, but only daughters: and their brethren the sons of Kish took them to wife."],["1 Chronicles",23,23,"The sons of Mushi; Mahli, and Eder, and Jeremoth, three."],["1 Chronicles",23,24,"These were the sons of Levi according to the houses of their fathers; the heads of father's houses, as they were counted by number of names by their polls, who did the work for the service of the house of the Lord, from the age of twenty years and upwards."],["1 Chronicles",23,25,"For David said, The Lord God of Israel has given rest to his people, that they may dwell in Jerusalem forever:"],["1 Chronicles",23,26,"and also to the Levites that they shall no more need to carry the tabernacle, nor any vessels of it for its service."],["1 Chronicles",23,27,"For by the last ordinances of David the Levites were numbered from twenty years old and above:"],["1 Chronicles",23,28,"because their station was at the side of the sons of Aaron for the service of the house of the Lord, in the courts, and in the chambers, and in the purifying of all holy things, and the work of the service of the house of God;"],["1 Chronicles",23,29,"both for the showbread, and for the fine flour for a meal offering, and for the unleavened cakes, and for that which is baked in the pan, and for that which is fried, and for all manner of measure and size;"],["1 Chronicles",23,30,"and to stand every morning to thank and praise the Lord, and likewise at evening;"],["1 Chronicles",23,31,"and whenever burnt sacrifices are offered to the Lord on the sabbaths, on the new moons, and on the appointed seasons, by number, according to the order commanded to them, continually before the Lord:"],["1 Chronicles",23,32,"and that they should keep the charge of the Tent of Meeting, and the charge of the holy place, and the charge of the sons of Aaron their brethren, for the service of the house of the Lord."],["1 Chronicles",24,1,"The divisions of the sons of Aaron. The sons of Aaron; Nadab, and Abihu, Eleazar, and Ithamar."],["1 Chronicles",24,2,"But Nadab and Abihu died before their father, and had no children: therefore Eleazar and Ithamar executed the priest's office."],["1 Chronicles",24,3,"And David and Zadok of the sons of Eleazar, and Ahimelech of the sons of Ithamar, divided them up according to their offices in their service."],["1 Chronicles",24,4,"And there were more chief men found of the sons of Eleazar than of the sons of Ithamar; and thus they were divided. Among the sons of Eleazar there were sixteen heads of fathers' houses and among the sons of Ithamar eight for the houses of their fathers."],["1 Chronicles",24,5,"Thus were they divided by lot, one sort with another; for there were officers of the sanctuary, and officers of God, among the sons of Eleazar, and of the sons of Ithamar."],["1 Chronicles",24,6,"And Shemaiah the son of Nethaneel the scribe, one of the Levites, recorded them in the presence of the king, and the princes, and Zadok the priest, and Ahimelech the son of Abiathar, and the heads of the fathers' houses of the priests and Levites: one father's house being chosen for Eleazar, and one chosen for Ithamar."],["1 Chronicles",24,7,"Now the first lot fell to Jehoiarib, the second to Jedaiah,"],["1 Chronicles",24,8,"the third to Harim, the fourth to Seorim,"],["1 Chronicles",24,9,"the fifth to Malchijah, the sixth to Mijamin,"],["1 Chronicles",24,10,"the seventh to Hakkoz, the eighth to Abijah,"],["1 Chronicles",24,11,"the ninth to Jeshua, the tenth to Shechaniah,"],["1 Chronicles",24,12,"the eleventh to Eliashib, the twelfth to Jakim,"],["1 Chronicles",24,13,"the thirteenth to Huppah, the fourteenth to Jeshebeab,"],["1 Chronicles",24,14,"the fifteenth to Bilgah, the sixteenth to Immer,"],["1 Chronicles",24,15,"the seventeenth to Hezir, the eighteenth to Happizzez,"],["1 Chronicles",24,16,"the nineteenth to Pethahiah, the twentieth to Ezekiel,"],["1 Chronicles",24,17,"the twenty first to Jachin, the twenty second to Gamul,"],["1 Chronicles",24,18,"the twenty third to Delaiah, the twenty fourth to Maaziah."],["1 Chronicles",24,19,"These were the orderings of them in their service to come into the house of the Lord, according to the form prescribed to them by the hand of Aaron their father, as the Lord God of Israel had commanded him."],["1 Chronicles",24,20,"And the rest of the sons of Levi were: of the sons of Amram; Shubael: of the sons of Shubael; Jehdeiah."],["1 Chronicles",24,21,"Of Rehabiah: of the sons of Rehabiah, the chief was Isshiah."],["1 Chronicles",24,22,"Of the Izharites; Shelomoth: of the sons of Shelomoth; Jahath."],["1 Chronicles",24,23,"And the sons of Jeriah: Amariah the second, Jahaziel the third, Jekameam the fourth."],["1 Chronicles",24,24,"Of the sons of Uzziel; Micah: of the sons of Micah; Shamir."],["1 Chronicles",24,25,"The brother of Micah was Isshiah: of the sons of Isshiah; Zechariah."],["1 Chronicles",24,26,"The sons of Merari were Mahli and Mushi: the sons of Jaaziah; Beno."],["1 Chronicles",24,27,"The sons of Merari by Jaaziah; Beno, and Shoham, and Zaccur, and Ibri."],["1 Chronicles",24,28,"Of Mahli came Eleazar, who had no sons."],["1 Chronicles",24,29,"Concerning Kish: the son of Kish was Jerahmeel."],["1 Chronicles",24,30,"And the sons of Mushi; Mahli, and Eder, and Jerimoth. These were the sons of the Levites according to the houses of their fathers."],["1 Chronicles",24,31,"These also cast lots in the same manner as their brethren the sons of Aaron, in the presence of David the king, and Zadok, and Ahimelech, and the heads of the fathers' houses of the priests and Levites; the head of each father's house in the same manner as his younger brother."],["1 Chronicles",25,1,"And David and the captains of the host separated for the service certain of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with lyres, with lutes, and with cymbals: and the number of the workmen according to their service was:"],["1 Chronicles",25,2,"of the sons of Asaph; Zechur, and Joseph, and Nethaniah, and Asarelah, the sons of Asaph, under the hands of Asaph, who prophesied according to the order of the king."],["1 Chronicles",25,3,"Of Jeduthun: the sons of Jeduthun; Gedaliah, and Zeri, and Isaiah, Hashabiah, and Mattithiah; six, under the hands of their father Jeduthun, who prophesied with a lyre, to give thanks and to praise the Lord."],["1 Chronicles",25,4,"Of Heman: the sons of Heman; Bukkiah, Mattaniah, Uzziel, Shebuel, and Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, and Romamti-ezer, Joshbekashah, Mallothi, Hothir, and Mahazioth:"],["1 Chronicles",25,5,"all these were the sons of Heman the king's seer according to the word of God, who bade to lift up his horn. And God gave to Heman fourteen sons and three daughters."],["1 Chronicles",25,6,"All these were under the hands of their father for song in the house of the Lord, with cymbals, lutes, and lyres, for the service of the house of God, according to the king's order Asaph, Jeduthun, and Heman."],["1 Chronicles",25,7,"So the number of them, with their brethren who were instructed in the songs of the Lord, all who were skilful, was two hundred and eighty eight."],["1 Chronicles",25,8,"And they cast lots, watch against watch, the small and the great alike, the teacher together with the pupil."],["1 Chronicles",25,9,"Now the first lot came out for Asaph to Joseph: the second to Gedaliah; he with his brethren and sons were twelve:"],["1 Chronicles",25,10,"the third to Zaccur, his sons and his brethren, twelve:"],["1 Chronicles",25,11,"the fourth to Izri, his sons, and his brethren, twelve:"],["1 Chronicles",25,12,"the fifth to Nethaniah, his sons, and his brethren, twelve:"],["1 Chronicles",25,13,"the sixth to Bukkiah, his sons, and his brethren, twelve:"],["1 Chronicles",25,14,"the seventh to Jesharelah, his sons and his brethren, twelve."],["1 Chronicles",25,15,"the eighth to Isaiah, his sons, and his brethren, twelve:"],["1 Chronicles",25,16,"the ninth to Mattaniah, his sons, and his brethren, twelve:"],["1 Chronicles",25,17,"the tenth to Shimei, his sons, and his brethren, twelve:"],["1 Chronicles",25,18,"the eleventh to Azareel, his sons, and his brethren, twelve:"],["1 Chronicles",25,19,"the twelfth to Hashabiah, his sons, and his brethren, twelve:"],["1 Chronicles",25,20,"the thirteenth to Shubael, his sons, and his brethren, twelve:"],["1 Chronicles",25,21,"the fourteenth to Mattithiah, his sons, and his brethren, twelve:"],["1 Chronicles",25,22,"the fifteenth to Jeremoth, his sons, and his brethren, twelve:"],["1 Chronicles",25,23,"the sixteenth, to Hananiah, his sons, and his brethren, twelve:"],["1 Chronicles",25,24,"the seventeenth to Joshbekashah, his sons, and his brethren, twelve:"],["1 Chronicles",25,25,"the eighteenth to Hanani, his sons, and his brethren, twelve:"],["1 Chronicles",25,26,"the nineteenth to Mallothi, his sons, and his brethren, twelve:"],["1 Chronicles",25,27,"the twentieth to Eliyyata, his sons, and his brethren, twelve:"],["1 Chronicles",25,28,"the twenty first to Hothir, his sons, and his brethren, twelve:"],["1 Chronicles",25,29,"the twenty second to Giddalti, his sons, and his brethren, twelve:"],["1 Chronicles",25,30,"the twenty third to Mahazioth, his sons, and his brethren, twelve:"],["1 Chronicles",25,31,"the twenty fourth to Romamti-ezer, his sons, and his brethren, twelve."],["1 Chronicles",26,1,"Concerning the divisions of the gatekeepers: of the Korhites was Meshelemiah the son of Kore, of the sons of Asaph."],["1 Chronicles",26,2,"And the sons of Meshelemiah were, Zechariah the firstborn, Jediael the second, Zebadiah the third, Jathniel the fourth,"],["1 Chronicles",26,3,"Elam the fifth, Jehohanan the sixth, Elihoenai the seventh."],["1 Chronicles",26,4,"And Obed-edom had sons, Shemaiah the firstborn, Jehozabad the second, Joah the third, and Sacar the fourth, and Nethaneel the fifth,"],["1 Chronicles",26,5,"Ammiel the sixth, Issachar the seventh, Peulthai the eighth: for God blessed him."],["1 Chronicles",26,6,"Also to Shemaiah his son were sons born, who ruled throughout the house of their father: for they were mighty men at arms."],["1 Chronicles",26,7,"The sons of Shemaiah; Othni, and Rephael, and Obed, Elzabad, whose brethren were strong men, Elihu, and Semachiah."],["1 Chronicles",26,8,"All these of the sons of Obed-edom: they and their sons and their brethren, able men for strength for the service, were sixty two of Obed-edom."],["1 Chronicles",26,9,"And Meshelemiah had sons and brothers, strong men, eighteen."],["1 Chronicles",26,10,"Also Hosah, of the children of Merari, had sons; Shimri the chief, (for though he was not the firstborn, yet his father made him the chief;)"],["1 Chronicles",26,11,"Hilkiah the second, Tebaliah the third, Zechariah the fourth: all the sons and brothers of Hosah were thirteen."],["1 Chronicles",26,12,"Among these were the divisions of the gatekeepers, among the chief men, having watches in the same manner as their brethren, to minister in the house of the Lord."],["1 Chronicles",26,13,"And they cast lots, the small as well as the great, according to the houses of their fathers, for every gate."],["1 Chronicles",26,14,"And the lot eastward fell to Shelemiah. Then for Zechariah his son, a wise counsellor, they cast lots; and his lot came out northwards."],["1 Chronicles",26,15,"To Obed-edom southwards; and to his sons the house of Asuppim."],["1 Chronicles",26,16,"To Shuppim and Hosah westwards, with the gate Shallecheth, by the causeway that goes up, ward against ward."],["1 Chronicles",26,17,"Eastwards were six Levites, northwards four a day, southwards four a day, and towards Asuppim two and two."],["1 Chronicles",26,18,"At Parbar westwards, four at the causeway, and two at Parbar."],["1 Chronicles",26,19,"These are the divisions of the gatekeepers, among the sons of Korah, and among the sons of Merari."],["1 Chronicles",26,20,"And of the Levites, Ahijah was over the treasures of the house of God, and over the treasures of the holy things."],["1 Chronicles",26,21,"The sons of Laadan; the sons of the Gershonites belonging to Laadan, the heads of fathers' houses, of Laadan the Gershonite, were Jehieli."],["1 Chronicles",26,22,"The sons of Jehieli; Zetham, and Joel his brother, who were over the treasures of the house of the Lord."],["1 Chronicles",26,23,"Of the Amramites, the Izharites, the Hebronites, and the Uzzielites:"],["1 Chronicles",26,24,"and Shebuel the son of Gershom, the son of Moses, was ruler of the treasures."],["1 Chronicles",26,25,"And his brethren by Eliezer; Rehabiah his son, and Isaiah his son, and Joram his son, and Zichri his son, and Shelomoth his son."],["1 Chronicles",26,26,"This Shelomoth and his brethren were over all the treasures of the dedicated things, which David the king, and the heads of the fathers' houses, the captains over thousands and hundreds, and the captains of the host, had dedicated."],["1 Chronicles",26,27,"Out of the spoils won in battles did they dedicate to maintain the house of the Lord."],["1 Chronicles",26,28,"And all that Samuel the seer, and Saul the son of Kish, and Abner the son of Ner, and Joab the son of Zeruiah, had dedicated; and whoever had dedicated anything, it was under the hand of Shelomith, and of his brethren."],["1 Chronicles",26,29,"Of the Izharites, Chenaniah and his sons were for the outward business over Israel, for officers and judges."],["1 Chronicles",26,30,"And of the Hebronites, Hashabiah and his brethren, men at arms, one thousand seven hundred, had the oversight of Israel on this side of the Jordan westward in all the business of the Lord, and in the service of the king."],["1 Chronicles",26,31,"Among the Hebronites was Jeriah the chief, among the Hebronites, according to the generations of his fathers. In the fortieth year of the reign of David they were sought for, and there were found among them mighty men at arms at Jazer of Gilead."],["1 Chronicles",26,32,"And his brethren, men at arms, two thousand seven hundred heads of fathers' houses, whom king David made rulers over the Reubenites, the God, and the half tribe of Manasseh, for every matter pertaining to God, and for the affairs of the king."],["1 Chronicles",27,1,"Now the children of Israel after their number, namely, heads of fathers' houses and captains of thousands and hundreds, and their officers who served the king in any matter of the divisions, who came in and went out month by month throughout all the months of the year; in every division were twenty four thousand."],["1 Chronicles",27,2,"Over the first division for the first month was Jashobeam the son of Zabdiel: and in his division were twenty four thousand."],["1 Chronicles",27,3,"Of the children of Pharez the chief of all the captains of the host for the first month."],["1 Chronicles",27,4,"And over the division of the second month was Dodai an Ahohite, and his division, and Mikloth the ruler in his division were twenty four thousand."],["1 Chronicles",27,5,"The third captain of the host for the third month was Benaiah the son of Jehoiada, a chief priest: and in his division were twenty four thousand."],["1 Chronicles",27,6,"This is that Benaiah, who was the mighty one of the thirty, and over the thirty: and in his division was Ammizabad his son."],["1 Chronicles",27,7,"The fourth captain for the fourth month was Asahel the brother of Joab, and Zebadiah his son after him: and in his division were twenty four thousand."],["1 Chronicles",27,8,"The fifth captain for the fifth month was Shamhuth of Jirzah: and in his division were twenty four thousand."],["1 Chronicles",27,9,"The sixth captain for the sixth month was Ira the son of Ikkesh the Tekoite: and in his division, were twenty four thousand."],["1 Chronicles",27,10,"The seventh captain for the seventh month was Helez the Pelonite, of the children of Ephraim: and in his division were twenty four thousand."],["1 Chronicles",27,11,"The eighth captain for the eighth month was Sibbechai the Hushathite, of the Zarhites: and in his division were twenty four thousand."],["1 Chronicles",27,12,"The ninth captain for the ninth month was Abiezer the Antothite, of the Benyemini: and in his division were twenty four thousand."],["1 Chronicles",27,13,"The tenth captain for the tenth month was Maharai the Netophathite, of the Zarhites: and in his division were twenty four thousand."],["1 Chronicles",27,14,"The eleventh captain for the eleventh month was Benaiah the Pirathonite, of the children of Ephraim: and in his division were twenty four thousand."],["1 Chronicles",27,15,"The twelfth captain for the twelfth month was Heldai the Netophathite, of Othniel: and in his division were twenty four thousand."],["1 Chronicles",27,16,"Furthermore over the tribes of Israel: the ruler of the Reubenites was Eliezer the son of Zichri: of the Simeonites, Shephatiah the son of Maachah:"],["1 Chronicles",27,17,"of the Levites, Hashabiah the son of Kemuel: of the sons of Aaron, Zadok:"],["1 Chronicles",27,18,"of Judah, Elihu, one of the brothers of David: of Issachar, Omri the son of Michael:"],["1 Chronicles",27,19,"of Zebulun, Ishmaiah the son of Obadiah: of Naphtali, Jerimoth the son of Azriel:"],["1 Chronicles",27,20,"of the children of Ephraim, Hoshea the son of Azaziah: of the half tribe of Manasseh, Joel the son of Pedaiah:"],["1 Chronicles",27,21,"of the half tribe of Manasseh in Gilead, Jiddo the son of Zechariah: of Benjamin, Jaasiel the son of Abner:"],["1 Chronicles",27,22,"of Dan, Azareel the son of Jeroham. These were the princes of the tribes of Israel."],["1 Chronicles",27,23,"But David did not take the number of them from twenty years old and under: because the Lord had said he would increase Israel like the stars of the heavens."],["1 Chronicles",27,24,"Joab the son of Zeruiah began to count, but he did not finish, because there fell wrath for it against Israel; nor was the number put in the account of the chronicles of king David."],["1 Chronicles",27,25,"And over the king's treasures was Azmaveth the son of Adiel: and over the storehouses in the fields, in the cities, and in the villages, and in the towers, was Jonathan the son of Uzziah:"],["1 Chronicles",27,26,"and over those who did the work of the field for the tillage of the ground was Ezri the son of Chelub:"],["1 Chronicles",27,27,"and over the vineyards was Shimei the Ramathite: over the increase of the vineyards for the wine cellars was Zabdi the Shiphmite:"],["1 Chronicles",27,28,"and over the olive trees and the sycamore trees that were in the low plains was Baal-hanan the Gederite: and over the cellars of oil was Joash:"],["1 Chronicles",27,29,"and over the herds which fed in the Sharon was Sharonite the Sharonite: and over the herds that were in the valleys was Shaphat the son of Adlai:"],["1 Chronicles",27,30,"and over the camels was Obil the Ishmaelite: and over the asses was Jehdeiah the Meronothite:"],["1 Chronicles",27,31,"and over the flocks was Jaziz the Hagerite. All these were the stewards of the property which belonged to king David."],["1 Chronicles",27,32,"And Jonathan David's uncle was a counsellor, a wise man, and a scribe: and Jehiel the son of Hachmoni was with the king's sons:"],["1 Chronicles",27,33,"and Ahithophel was the king's counsellor: and Hushai the Archite was the king's companion:"],["1 Chronicles",27,34,"and after Ahithophel came Jehoiada the son of Benaiah, and Abiathar: and the general of the king's army was Joab."],["1 Chronicles",28,1,"And David assembled all the princes of Israel, the princes of the tribes, and the captains of the companies that served the king by divisions, and the captains over the thousands, and captains over the hundreds, and the stewards over all the property and possessions of the king, and of his sons, with the officers, and with the mighty men, and with all the men at arms to Jerusalem."],["1 Chronicles",28,2,"Then David the king stood up upon his feet, and said, Hear me, my brethren, and my people: As for me, I had it in my heart to build a house of rest for the ark of the covenant of the Lord, and for the footstool of our God, and I had made ready for building:"],["1 Chronicles",28,3,"but God said to me, Thou shalt not build a house for my name, because thou hast been a man of battles, and hast shed blood."],["1 Chronicles",28,4,"Yet the Lord God of Israel chose me before all the house of my father to be king over Israel forever: for he has chosen Judah to be the ruler; and out of the house of Judah, the house of my father; and among the sons of my father he took pleasure in me to make me king over all Israel:"],["1 Chronicles",28,5,"and of all my sons, (for the Lord has given me many sons), he has chosen Solomon my son to sit upon the throne of the kingdom of the Lord over Israel."],["1 Chronicles",28,6,"And he said to me, Solomon thy son, he shall build my house and my courts: for I have chosen him to be my son, and I will be a father to him."],["1 Chronicles",28,7,"Moreover I will establish his kingdom forever, if he be constant to do my commandments and my judgments, as at this day."],["1 Chronicles",28,8,"Now therefore in the sight of all Israel the congregation of the Lord, and in the hearing of our God, observe and seek out all the commandments of the Lord your God: that you may possess this good land, and leave it for an inheritance for your children after you forever."],["1 Chronicles",28,9,"And thou, Solomon my son, know thou the God of thy father, and serve him with a perfect heart and with a willing mind: for the Lord searches all hearts, and understands all the imaginations of the thoughts: if thou seek him, he will be found by thee; but if thou forsake him, he will cast thee off forever."],["1 Chronicles",28,10,"Take heed now; for the Lord has chosen thee to build a house for the sanctuary: be strong, and do it."],["1 Chronicles",28,11,"Then David gave to Solomon his son the pattern of the porch, and of its houses and of its treasuries, and of its upper chambers, and of its inner rooms, and of the place of the ark with its covering,"],["1 Chronicles",28,12,"and the pattern of all that he had by the spirit, of the courts of the house of the Lord, and of all the chambers round about, of the treasuries of the house of God, and of the treasuries of the holy things:"],["1 Chronicles",28,13,"also for the divisions of the priests and the Levites, and for all the work of the service of the house of the Lord, and for all the vessels of service in the house of the Lord."],["1 Chronicles",28,14,"He gave of gold by weight for things of gold, for all instruments of all manner of service; silver also for all instruments of silver by weight, for all instruments of every kind of service:"],["1 Chronicles",28,15,"both the weight for the candlesticks of gold, and for their lamps of gold, by weight for every candlestick, and for its lamps: and for the candlesticks of silver by weight, for the candlestick, and for its lamps, according to the use of every candlestick."],["1 Chronicles",28,16,"And by weight he gave gold for the tables of showbread, for every table; and likewise silver for the tables of silver:"],["1 Chronicles",28,17,"also pure gold for the forks, and the basins, and the jars: and for the golden bowls by weight for every bowl; and likewise by weight for every bowl of the silver bowls:"],["1 Chronicles",28,18,"and for the altar of incense refined gold by weight; and gold for the pattern of the chariot, that is the keruvim, that spread out their wings, and cover the ark of the covenant of the Lord."],["1 Chronicles",28,19,"All this, said he, is put in writing by the hand of the Lord who instructed me, all the works of this pattern."],["1 Chronicles",28,20,"And David said to Solomon his son, Be strong and of good courage, and do it: do not fear, or be dismayed: for the Lord God, my God, will be with thee; he will not fail thee, or forsake thee, until thou hast finished all the work for the service of the house of the Lord."],["1 Chronicles",28,21,"And, behold, the divisions of the priests and the Levites, for all the service of the house of God: and there shall be with thee for all manner of workmanship every willing skilful man, for any manner of service: also the princes and all the people will be wholly at thy commandment."],["1 Chronicles",29,1,"And David the king said to all the congregation, Solomon my son, whom alone God has chosen, is yet young and tender, and the work is great: for the palace is not for man, but for the Lord God."],["1 Chronicles",29,2,"Now I have prepared with all my might for the house of my God the gold for things to be made of gold, and the silver for things of silver, and the brass for things of brass, the iron for things of iron, and wood for things of wood; Shoham stones, and stones to be set, glistering stones, and coloured stones; and all manner of precious stones, and marble stone in abundance."],["1 Chronicles",29,3,"Moreover, because I have set my affection on the house of my God, I have given of my own private treasure, of gold and silver, to the house of my God, over and above all that I have prepared for the holy house,"],["1 Chronicles",29,4,"three thousand talents of gold, of the gold of Ophir, and seven thousand talents of refined silver, with which to overlay the walls of the houses:"],["1 Chronicles",29,5,"the gold for things of gold, and the silver for things of silver, and for all manner of work to be made by the hands of artificers. And who then is willing to consecrate himself this day to the Lord?"],["1 Chronicles",29,6,"Then the chief of the fathers' houses and princes of the tribes of Israel, and the captains of thousands and of hundreds, with the rulers of the king's work, offered willingly,"],["1 Chronicles",29,7,"and gave for the service of the house of God five thousand talents and ten thousand darics of gold, and ten thousand talents of silver, and eighteen thousand talents of brass, and one hundred thousand talents of iron."],["1 Chronicles",29,8,"And they with whom precious stones were found gave them to the treasure of the house of the Lord, by the hand of Jehiel the Gershonite."],["1 Chronicles",29,9,"Then the people rejoiced, for having offered willingly, because with a perfect heart they offered willingly to the Lord: and David the king also rejoiced with great joy."],["1 Chronicles",29,10,"Wherefore David blessed the Lord before all the congregation: and David said, Blessed be Thou, Lord God of Israel our father, forever and ever."],["1 Chronicles",29,11,"Thine, O Lord, is the greatness, and the power, and the glory, and the victory, and the majesty: for all that is in heaven and on earth is Thine; Thine is the kingdom, O Lord, and Thou art exalted as head above all."],["1 Chronicles",29,12,"Both riches and honour come of Thee, and Thou reignest over all; and in Thy hand is power and might; and in Thy hand it is to make great, and to give strength to all."],["1 Chronicles",29,13,"Now therefore, our God, we thank Thee, and praise Thy glorious name."],["1 Chronicles",29,14,"But who am I, and what is my people, that we should be able thus to offer willingly after this sort? for all things come of Thee, and of Thy own have we given Thee."],["1 Chronicles",29,15,"For we are strangers before Thee, and sojourners, as were all our fathers: our days on the earth are as a shadow, and there is no abiding."],["1 Chronicles",29,16,"O Lord our God, all this store that we have prepared, to build Thee a house for Thy holy name comes of Thy hand, and is all Thy own."],["1 Chronicles",29,17,"I know also, my God, that Thou triest the heart, and hast pleasure in uprightness. As for me, in the uprightness of my heart I have willingly offered all these things: and now I have seen Thy people, who are present here, offering joyfully and freely to Thee."],["1 Chronicles",29,18,"O Lord God of Abraham, Isaac and of Israel, our fathers, keep this forever in the imagination of the thoughts of the heart of Thy people, and direct their hearts to Thee:"],["1 Chronicles",29,19,"And give to Solomon my son a perfect heart, to keep Thy commandments, Thy testimonies, and Thy statutes, and to do all these things, and to build the palace, for which I have made provision."],["1 Chronicles",29,20,"And David said to all the congregation, Now bless the Lord your God. And all the congregation blessed the Lord God of their fathers, and bowed down their heads, and prostrated themselves before the Lord, and the king."],["1 Chronicles",29,21,"And they sacrificed sacrifices to the Lord, and offered burnt offerings to the Lord, on the morrow after that day, a thousand bullocks, a thousand rams, a thousand lambs, with their drink offerings, and sacrifices in abundance for all Israel:"],["1 Chronicles",29,22,"and they did eat and drink before the Lord on that day with great gladness. And they made Solomon the son of David king the second time, and anointed him to the Lord to be the chief governor, and Zadok to be priest."],["1 Chronicles",29,23,"Then Solomon sat on the throne of the Lord as king instead of David his father, and prospered; and all Israel obeyed him."],["1 Chronicles",29,24,"And all the princes, and the mighty men, and all the sons likewise of king David, submitted themselves to Solomon the king."],["1 Chronicles",29,25,"And the Lord magnified Solomon exceedingly in the sight of all Israel, and bestowed upon him such royal majesty as had not been on any king before him in Israel."],["1 Chronicles",29,26,"Thus David the son of Jesse reigned over all Israel."],["1 Chronicles",29,27,"And the time that he reigned over Israel was forty years; seven years he reigned in Hebron, and thirty three years he reigned in Jerusalem."],["1 Chronicles",29,28,"And he died in a good old age, full of days, riches, and honour: and Solomon his son reigned in his stead."],["1 Chronicles",29,29,"Now the acts of David the king, first and last, behold, they are written in the book of Samuel the seer, and in the book of Nathan the prophet, and in the book of Gad the seer,"],["1 Chronicles",29,30,"with all his reign and his might, and the times that went over him, and over Israel, and over all the kingdoms of the countries."]]);
